window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[168]={"id":"168","numero":168,"titre":"Infections à herpès virus","objectifs":[{"id":"168-1","rang":"A","rubrique":"Epidémiologie","titre":"Connaître les modes de transmissions pour l’herpès virus (HSV) et le virus varicelle-zona (VZV)","contenu":"<div class=\"obj-callout success\"><strong>À retenir.</strong> L'<span class=\"kw-def\">homme est le seul réservoir</span> des herpès virus. Ce sont des <span class=\"kw-def\">virus enveloppés</span>, donc <span class=\"kw-clinique\">fragiles</span> dans l'environnement → la <strong>transmission indirecte (objets) est rare</strong> ; c'est le <span class=\"kw-etio\">contact direct cutanéo-muqueux</span> qui domine.</div>\n\n      <h4 class=\"kw-def\"><span class=\"kw-etio\">HSV</span>-1 et HSV-2 — transmission par <span class=\"kw-def\">contact</span> direct</h4>\n      <ul>\n        <li><span class=\"kw-etio\">Contact direct cutanéo-muqueux</span> : <span class=\"kw-etio\">salive</span> / baiser (<span class=\"kw-etio\">HSV</span>-1), <span class=\"kw-etio\">rapports sexuels</span> (HSV-2), <span class=\"kw-def\">contact</span> <span class=\"kw-etio\">per-partum</span> lors du passage dans la filière génitale (herpès néonatal).</li>\n        <li>Favorisée par toute <span class=\"kw-clinique\">altération du revêtement épithélial</span> : <span class=\"kw-clinique\">érosion</span>, dermatose <span class=\"kw-etio\">inflammatoire</span>, rapport traumatisant.</li>\n        <li><span class=\"kw-etio\">Passage transplacentaire</span> (in utero) et <span class=\"kw-etio\">allaitement maternel</span> (très rare) possibles.</li>\n        <li><strong><span class=\"kw-etio\">HSV</span>-1 :</strong> tropisme <span class=\"kw-clinique\">oro-facial</span> ++ (mais HSV-2 possible). <strong>HSV-2 :</strong> tropisme <span class=\"kw-clinique\">génital</span> ++ (mais HSV-1 possible, en augmentation).</li>\n      </ul>\n\n      <h4 class=\"kw-def\"><span class=\"kw-etio\">VZV</span> — transmission par <span class=\"kw-def\">contact</span> ET aérienne</h4>\n      <ul>\n        <li><span class=\"kw-etio\">Transmission par contact</span> direct avec <span class=\"kw-clinique\">les</span> lésions cutanéo-muqueuses.</li>\n        <li><span class=\"kw-etio\">Transmission aérienne</span> (respiratoire) — la varicelle est <span class=\"kw-alerte\">la maladie éruptive la plus contagieuse</span> → impose des <span class=\"kw-alerte\">précautions de type AIR</span> en milieu de soins.</li>\n        <li>Risque de <span class=\"kw-alerte\">transmission fœtale</span> si varicelle pendant la <span class=\"kw-ci\">grossesse</span> (surtout en péri-partum).</li>\n      </ul>\n\n      <div class=\"callout callout-info\"><strong>Contagiosité.</strong> Varicelle : débute <span class=\"kw-chiffre\">1 à 2 jours avant</span> l'<span class=\"kw-clinique\">éruption</span> et persiste <span class=\"kw-chiffre\">≥ 5–7 jours</span> jusqu'à ce que toutes <span class=\"kw-clinique\">les</span> vésicules soient croûteuses. Le <span class=\"kw-clinique\">zona</span>, lui, est contagieux par <span class=\"kw-def\">contact</span> direct (excrétion <span class=\"kw-etio\">virale</span> localisée).</div>","frequence":1},{"id":"168-2","rang":"B","rubrique":"Epidémiologie","titre":"Connaître les principales données épidémiologiques des infections à HSV et VZV","contenu":"<div class=\"obj-callout success\"><strong>Idée-force.</strong> <span class=\"kw-clinique\">Les</span> herpès virus sont des infections <strong>ubiquitaires et très fréquentes</strong>, avec une <span class=\"kw-etio\">séroprévalence qui augmente avec l'âge</span> : la quasi-totalité des adultes est porteuse de <span class=\"kw-etio\">HSV</span>-1 et/ou de VZV à l'état latent.</div>\n\n      <table >\n        <thead><tr><th>Virus</th><th>Données clés de séroprévalence / <span class=\"kw-def\">incidence</span></th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\">HSV-1</span></td>\n            <td><span class=\"kw-clinique\">Primo-infection</span> dans <span class=\"kw-clinique\">les</span> premières années (<span class=\"kw-chiffre\">1–4 ans</span>) : <span class=\"kw-chiffre\">≈ 80 %</span> des enfants <span class=\"kw-chiffre\">≥ 5 ans</span> ont des AC anti-<span class=\"kw-etio\">HSV</span>-1 ; <span class=\"kw-chiffre\">≈ 90 %</span> de séropositivité (<span class=\"kw-chiffre\">IgG</span>) chez l'adulte.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">HSV-2</span></td>\n            <td><span class=\"kw-clinique\">Primo-infection</span> lors des 2 premières décennies de vie sexuelle. Séroprévalence (<span class=\"kw-chiffre\">IgG</span>) <span class=\"kw-clinique\">en augmentation</span> : population générale <span class=\"kw-chiffre\">15–30 %</span> ; hétérosexuels avec <span class=\"kw-clinique\">IST</span> <span class=\"kw-chiffre\">50 %</span> ; HSH <span class=\"kw-chiffre\">70 %</span> ; prostitution / <span class=\"kw-etio\">VIH</span> <span class=\"kw-chiffre\">90 %</span>.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Varicelle</span><br><em>(<span class=\"kw-clinique\">primo-infection</span> <span class=\"kw-etio\">VZV</span>)</em></td>\n            <td>Séroprévalence <span class=\"kw-chiffre\">&gt; 90 %</span> chez l'adulte. <span class=\"kw-chiffre\">600 000 – 700 000</span> cas/an en France. <span class=\"kw-chiffre\">≈ 90 %</span> surviennent chez l'enfant de <span class=\"kw-chiffre\">1–14 ans</span> (âge moyen <span class=\"kw-chiffre\">4 ans</span>).</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Zona</span><br><em>(réactivation <span class=\"kw-etio\">VZV</span>)</em></td>\n            <td>Atteint <span class=\"kw-chiffre\">≈ 20 %</span> de la population (1,4 / 100 personnes-année). Prédominance <span class=\"kw-chiffre\">&gt; 50 ans</span> (baisse de l'immunité liée à l'âge) ; rare chez l'enfant.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\"><strong>Drapeau épidémiologique.</strong> Un <span class=\"kw-clinique\">zona avant 50 ans</span> ou une <span class=\"kw-clinique\">varicelle grave de l'adulte</span> doit faire rechercher une <span class=\"kw-alerte\">immunodépression sous-jacente</span> (notamment <span class=\"kw-etio\">sérologie VIH</span>, hémopathie).</div>","frequence":0},{"id":"168-3","rang":"B","rubrique":"Physiopathologie","titre":"Connaître les principales caractéristiques virales et la réponse immunitaire aux infections à herpès virus","contenu":"<div class=\"obj-callout success\"><strong>Définition.</strong> <span class=\"kw-clinique\">Les</span> herpès virus sont des <span class=\"kw-def\">virus enveloppés à ADN</span>. Leur trait commun : après la <span class=\"kw-def\">primo-infection</span>, ils établissent une <span class=\"kw-def\">infection latente à vie</span> dans certaines cellules, source de <span class=\"kw-def\">réactivations</span> et de <span class=\"kw-def\">récurrences</span>.</div>\n\n      <h4 class=\"kw-def\"><span class=\"kw-clinique\">Les</span> principaux herpès virus humains</h4>\n      <table >\n        <thead><tr><th>Virus</th><th>Manifestations principales</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\">HSV-1 / HSV-2</span><br><em>(Herpes simplex virus)</em></td>\n            <td><span class=\"kw-clinique\">Primo-infection</span> et réactivations <span class=\"kw-clinique\">muqueuses</span> · <span class=\"kw-alerte\">méningo-encéphalite</span> · <span class=\"kw-alerte\">infection néonatale</span> (si infection génitale maternelle à l'accouchement).</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">VZV</span><br><em>(Virus varicelle-<span class=\"kw-clinique\">zona</span>)</em></td>\n            <td><span class=\"kw-clinique\">Primo-infection</span> = <span class=\"kw-clinique\">varicelle</span> ; réactivation = <span class=\"kw-clinique\">zona</span>. Risque de transmission fœtale si varicelle pendant la <span class=\"kw-ci\">grossesse</span>.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">EBV</span></td>\n            <td><span class=\"kw-clinique\">Primo-infection</span> parfois symptomatique : <span class=\"kw-clinique\">mononucléose infectieuse</span> (adolescent / adulte jeune).</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">CMV</span><br><em>(Cytomégalovirus)</em></td>\n            <td><span class=\"kw-clinique\">Primo-infection</span> chez l'immunocompétent ; primo-infection + réactivation chez l'<span class=\"kw-etio\">immunodéprimé</span> ; <span class=\"kw-alerte\">infection fœtale</span> si primo-infection pendant la <span class=\"kw-ci\">grossesse</span>.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">HHV</span><br><em>(Human Herpes virus 6/7/8)</em></td>\n            <td>Roséole (<span class=\"kw-etio\">HHV-6</span>, plus rarement HHV-7) ; <span class=\"kw-etio\">HHV-8</span> : maladie de Kaposi, lymphome des séreuses, maladie de Castleman.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 class=\"kw-def\">Tropisme neuro-cutané de <span class=\"kw-etio\">HSV</span> et VZV</h4>\n      <ul>\n        <li><strong>1.</strong> <span class=\"kw-clinique\">Latence</span> dans <span class=\"kw-clinique\">les</span> <span class=\"kw-clinique\">neurones des ganglions sensitifs</span> (crâniens pour <span class=\"kw-etio\">HSV</span>-1, spinaux/sacrés pour HSV-2).</li>\n        <li><strong>2.</strong> <span class=\"kw-clinique\">Réactivation à expression cutanée</span> dans le territoire d'innervation correspondant.</li>\n        <li><strong>3.</strong> Voire <span class=\"kw-alerte\">réactivation encéphalique</span> (<span class=\"kw-clinique\">méningo-encéphalite</span>).</li>\n      </ul>\n\n      <div class=\"callout callout-warn\"><strong>Réponse immunitaire — point capital.</strong> Le contrôle de l'infection repose sur l'<span class=\"kw-bio\">immunité à médiation cellulaire</span>. Cela explique la <span class=\"kw-alerte\">gravité des infections chez les immunodéprimés</span> (<span class=\"kw-etio\">VIH</span>, greffés, <span class=\"kw-ttt\">immunosuppresseurs</span>). L'immunité <span class=\"kw-etio\">acquise</span> est <strong>partielle</strong> : elle n'empêche pas <span class=\"kw-clinique\">les</span> récurrences, et l'infection par un type d'<span class=\"kw-etio\">HSV</span> ne protège pas d'une infection par l'autre type.</div>","frequence":1},{"id":"168-4","rang":"A","rubrique":"Physiopathologie","titre":"Connaître les différentes phases cliniques d’infection des herpès virus","contenu":"<div class=\"obj-callout success\"><strong>Schéma en 3 temps.</strong> <span class=\"kw-def\">Primo-infection</span> → <span class=\"kw-def\">latence</span> (quiescence <span class=\"kw-etio\">virale</span> « sanctuaire » dans le ganglion sensitif, peu accessible à l'immunité et aux traitements) → <span class=\"kw-def\">réactivation</span>.</div>\n\n      <h4 class=\"kw-def\">1 · <span class=\"kw-clinique\">Primo-infection</span></h4>\n      <ul>\n        <li>1<sup>er</sup> <span class=\"kw-def\">contact</span> infectant muqueux ou cutané. Incubation <span class=\"kw-etio\">HSV</span> <span class=\"kw-chiffre\">2–7 jours</span>.</li>\n        <li>Cycle <span class=\"kw-etio\">viral</span> productif dans <span class=\"kw-clinique\">les</span> <span class=\"kw-clinique\">kératinocytes</span> → ballonisation → <span class=\"kw-clinique\">vésicules inflammatoires</span>.</li>\n        <li>Le plus souvent <span class=\"kw-clinique\">asymptomatique</span> (<span class=\"kw-chiffre\">≈ 80 %</span>) ; symptomatique dans <span class=\"kw-chiffre\">≈ 20 %</span>.</li>\n        <li>Puis <span class=\"kw-clinique\">migration antérograde</span> le long des nerfs sensitifs jusqu'au ganglion → installation de la latence.</li>\n      </ul>\n\n      <h4 class=\"kw-def\">2 · Latence</h4>\n      <ul>\n        <li>Transcription du génome <span class=\"kw-etio\">viral</span> <strong>sans synthèse protéique</strong> : le virus est « endormi » et <span class=\"kw-alerte\">non éradicable</span>.</li>\n      </ul>\n\n      <h4 class=\"kw-def\">3 · Réactivation (<span class=\"kw-alerte\">rupture</span> de quiescence)</h4>\n      <ul>\n        <li><span class=\"kw-clinique\">Migration rétrograde</span> du virus vers la peau / muqueuse → recolonisation du territoire d'innervation.</li>\n        <li>Deux formes :\n          <ul>\n            <li><span class=\"kw-clinique\">Récurrence</span> = réactivation <strong>symptomatique</strong> (<span class=\"kw-chiffre\">≈ 20 %</span>).</li>\n            <li><span class=\"kw-clinique\">Excrétion virale asymptomatique</span> = sans signe clinique mais <span class=\"kw-alerte\">contagieuse</span> (<span class=\"kw-chiffre\">≈ 80 %</span>).</li>\n          </ul>\n        </li>\n        <li><strong>Cas du <span class=\"kw-etio\">VZV</span> :</strong> <span class=\"kw-clinique\">primo-infection</span> = <span class=\"kw-clinique\">varicelle</span> ; réactivation symptomatique = <span class=\"kw-clinique\">zona</span>.</li>\n      </ul>","frequence":0},{"id":"168-5","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les modalités du diagnostic d’une primo infection et d’une récurrence à HSV 1 et 2","contenu":"<div class=\"obj-callout success\"><strong>Le diagnostic d'herpès cutanéo-muqueux est essentiellement clinique</strong> (hors <span class=\"kw-clinique\">méningo-encéphalite</span>). La <span class=\"kw-clinique\">lésion élémentaire</span> est une <span class=\"kw-clinique\">vésicule groupée en « bouquet »</span> sur fond érythémateux, évoluant vers des <span class=\"kw-clinique\">érosions post-vésiculeuses</span> arrondies, coalescentes, à contours polycycliques, puis des <span class=\"kw-clinique\">croûtes</span>.</div>\n\n      <h4 class=\"kw-def\"><span class=\"kw-clinique\">Primo-infection</span> symptomatique — tableaux selon le site</h4>\n      <ul>\n        <li><strong>Gingivostomatite herpétique</strong> (<span class=\"kw-etio\">HSV</span>-1, enfant) : forme la plus typique de <span class=\"kw-clinique\">primo-infection</span> orale.</li>\n        <li><strong>Herpès génital</strong> (<span class=\"kw-etio\">HSV-2</span><span class=\"kw-chiffre\"> 70–85 %</span>, <span class=\"kw-etio\">HSV</span>-1 en hausse) : <span class=\"kw-alerte\">IST</span>, 1<sup>re</sup> cause d'<span class=\"kw-clinique\">ulcération</span> génitale dans <span class=\"kw-clinique\">les</span> pays développés. Vulvovaginite aiguë <span class=\"kw-clinique\">brutale</span>, <span class=\"kw-alerte\">douleurs intenses</span>, érosions polycycliques, ± tableau pseudo-grippal et <span class=\"kw-clinique\">adénopathies</span> inguinales. <span class=\"kw-alerte\">Rétention urinaire</span> = <span class=\"kw-alerte\">signe de gravité</span>.</li>\n      </ul>\n\n      <h4 class=\"kw-def\">Récurrence herpétique</h4>\n      <ul>\n        <li><span class=\"kw-clinique\">Prodromes</span> stéréotypés (dysesthésie cuisante, picotements, <span class=\"kw-clinique\">prurit</span>) quelques heures avant.</li>\n        <li>Topographie <span class=\"kw-clinique\">stéréotypée</span> chez un patient donné (siège de la <span class=\"kw-clinique\">primo-infection</span>) : labiale &gt; génitale &gt; cutanée, nasale, oculaire.</li>\n        <li>Vésicules en bouquet → érosions → croûtes ; cicatrisation en <span class=\"kw-chiffre\">7–14 jours</span>. Contagiosité <span class=\"kw-chiffre\">2–4 jours</span>.</li>\n      </ul>\n\n      <h4 class=\"kw-def\">Examens — quand le clinique ne suffit pas</h4>\n      <table >\n        <thead><tr><th>Situation</th><th>Conduite</th></tr></thead>\n        <tbody>\n          <tr><td>Forme typique, <span class=\"kw-def\">terrain</span> non à risque</td><td><strong>Aucun examen</strong> : diagnostic clinique.</td></tr>\n          <tr><td>Diagnostic direct (forme atypique, grave, <span class=\"kw-def\">terrain</span> à risque)</td><td><span class=\"kw-bio\">PCR HSV</span> sur écouvillonnage de <span class=\"kw-clinique\">vésicule</span> récente = <strong>technique de référence</strong> (a remplacé la culture), résultat &lt;<span class=\"kw-chiffre\"> 24 h</span>, très sensible/spécifique.</td></tr>\n          <tr><td>Diagnostic indirect</td><td><span class=\"kw-bio\">Sérologie</span> : intérêt <strong>limité</strong> (<span class=\"kw-chiffre\">IgG</span> + chez <span class=\"kw-chiffre\">80 %</span> des adultes). Utile seulement pour documenter une <span class=\"kw-bio\">séroconversion</span> en <span class=\"kw-clinique\">primo-infection</span> (2 prélèvements à 10 j).</td></tr>\n        </tbody>\n      </table>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 162 — <span class=\"kw-clinique\">IST</span> · 169 — <span class=\"kw-etio\">VIH</span></em></p>","frequence":2},{"id":"168-6","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les facteurs favorisants des récurrences herpétiques","contenu":"<div class=\"callout callout-info\"><strong>Mécanisme.</strong> Toute baisse transitoire de l'<span class=\"kw-bio\">immunité à médiation cellulaire</span> ou toute agression locale du territoire peut déclencher une <span class=\"kw-alerte\">rupture</span> de la latence <span class=\"kw-etio\">virale</span>.</div>\n\n      <table >\n        <thead><tr><th>Catégorie de facteurs</th><th>Exemples</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-etio\">Infections intercurrentes</span></td><td>Épisode fébrile (« bouton de <span class=\"kw-clinique\">fièvre</span> »), infection <span class=\"kw-etio\">fongique</span>, bactérienne ou virale.</td></tr>\n          <tr><td><span class=\"kw-etio\">Facteurs physiques</span></td><td><span class=\"kw-clinique\">Rayons UV</span> / soleil, froid, traumatisme facial.</td></tr>\n          <tr><td><span class=\"kw-etio\">Facteurs physiologiques</span></td><td><span class=\"kw-clinique\">Cycle menstruel</span> (herpès cataménial), rapports sexuels (herpès génital).</td></tr>\n          <tr><td><span class=\"kw-etio\">Facteurs systémiques</span></td><td><span class=\"kw-alerte\">Immunodépression</span>, stress, <span class=\"kw-clinique\">asthénie</span>, fatigue.</td></tr>\n          <tr><td><span class=\"kw-etio\">Facteurs iatrogènes</span></td><td><span class=\"kw-ttt\">Immunosuppresseurs</span>, <span class=\"kw-ttt\">chirurgie</span> ou laser dans le territoire.</td></tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\"><strong>Seuil thérapeutique.</strong> Un nombre élevé de récurrences (<span class=\"kw-chiffre\">≥ 6 / an</span>) justifie d'envisager un <span class=\"kw-ttt\">traitement préventif</span> (cf. objectif Traitement).</div>","frequence":0},{"id":"168-7","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les modalités du diagnostic d’une varicelle et ses principales complications","contenu":"<div class=\"obj-callout success\"><strong>Diagnostic clinique.</strong> La <span class=\"kw-def\">varicelle</span> est la <span class=\"kw-clinique\">primo-infection</span> par le <span class=\"kw-def\">VZV</span>. Incubation <span class=\"kw-chiffre\">≈ 14 jours</span>. Tableau : <span class=\"kw-clinique\">exanthème vésiculeux prurigineux</span> fébrile, d'<span class=\"kw-clinique\">évolution</span> <span class=\"kw-clinique\">descendante</span> (cuir chevelu → face → tronc), respectant <span class=\"kw-clinique\">paumes et plantes</span>.</div>\n\n      <h4 class=\"kw-def\">Sémiologie de l'<span class=\"kw-clinique\">éruption</span></h4>\n      <ul>\n        <li><span class=\"kw-clinique\">Prurit +++</span>, <span class=\"kw-clinique\">fièvre</span> modérée (<span class=\"kw-chiffre\">38–39 °C</span>).</li>\n        <li><span class=\"kw-clinique\">Lésion</span> typique : <span class=\"kw-clinique\">vésicule</span> à contenu clair puis trouble, bordée d'une <span class=\"kw-clinique\">auréole rouge</span> = « <span class=\"kw-clinique\">goutte de rosée sur peau saine</span> », puis <span class=\"kw-clinique\">ombilication</span>, croûtes à <span class=\"kw-chiffre\">J4</span>, cicatrisation à <span class=\"kw-chiffre\">J10</span>.</li>\n        <li><span class=\"kw-clinique\">Évolution</span> par <span class=\"kw-clinique\">2–3 poussées</span> → coexistence d'<span class=\"kw-clinique\">éléments d'âges différents</span> (signe sémiologique majeur).</li>\n        <li>± <span class=\"kw-clinique\">énanthème buccal</span> érosif, micropolyadénopathies cervicales.</li>\n      </ul>\n\n      <h4 class=\"kw-def\">Principales complications (<span class=\"kw-chiffre\">3–5 %</span> des cas)</h4>\n      <table >\n        <thead><tr><th>Type</th><th>Détail</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-alerte\">Surinfections bactériennes</span><br><em>(<span class=\"kw-clinique\">les</span> plus fréquentes)</em></td>\n            <td>Favorisées par le grattage et <span class=\"kw-clinique\">les</span> <span class=\"kw-ci\">AINS</span>. <span class=\"kw-etio\">S. aureus</span>, <span class=\"kw-etio\">S. pyogenes</span> (SGA) : impétiginisation, mais aussi <span class=\"kw-alerte\">dermohypodermite / fasciite nécrosante</span>, syndromes toxiniques, <span class=\"kw-alerte\">sepsis</span>.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-alerte\">Pneumopathie varicelleuse</span></td>\n            <td>Surtout chez l'<span class=\"kw-etio\">adulte</span> (FR : tabac, <span class=\"kw-ci\">grossesse</span>). Survient <span class=\"kw-chiffre\">1–6 j</span> après l'<span class=\"kw-clinique\">éruption</span>. <span class=\"kw-clinique\">Toux, dyspnée, fièvre, hémoptysies</span> ± <span class=\"kw-alerte\">détresse respiratoire aiguë</span>. <span class=\"kw-imagerie\">Opacités micro- et macronodulaires</span>. Responsable de <span class=\"kw-chiffre\">≈ 30 %</span> des décès de la varicelle de l'adulte.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-alerte\">Neurologiques</span></td>\n            <td>Convulsions hyperthermiques ; <span class=\"kw-clinique\">cérébellite</span> (la plus fréquente, bénigne, guérit en ~15 j) ; <span class=\"kw-alerte\">encéphalite</span>, myélite. <span class=\"kw-alerte\">Syndrome de Reye</span> lié à l'<span class=\"kw-ci\">aspirine</span> (encéphalopathie + <span class=\"kw-etio\">stéatose</span> hépatique), <span class=\"kw-alerte\">mortel</span> dans <span class=\"kw-chiffre\">80 %</span> des cas.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-alerte\">Varicelle profuse</span></td>\n            <td>Forme ulcéro-nécrotique, <span class=\"kw-etio\">hémorragique</span> (immunodéprimé) ; <span class=\"kw-alerte\">purpura fulminans</span>, <span class=\"kw-alerte\">CIVD</span>, atteintes viscérales.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-danger\"><strong><span class=\"kw-ci\">Contre-indications</span> absolues dans la varicelle.</strong> <span class=\"kw-ci\">Pas d'aspirine</span> (risque de <span class=\"kw-clinique\">syndrome de Reye</span>) ; <span class=\"kw-ci\">pas d'AINS</span> (risque de <span class=\"kw-alerte\">fasciite nécrosante</span>) ; pas de topiques (talc, anesthésiques) qui masquent la surinfection.</div>\n\n      <h4 class=\"kw-def\">Terrains à risque de forme grave</h4>\n      <ul>\n        <li><span class=\"kw-etio\">Adulte</span>, adolescent &gt;<span class=\"kw-chiffre\"> 12 ans</span>, <span class=\"kw-etio\">femme enceinte</span>.</li>\n        <li><span class=\"kw-etio\">Nouveau-né</span> / nourrisson (surtout &lt;<span class=\"kw-chiffre\"> 1 an</span>), prématuré.</li>\n        <li><span class=\"kw-alerte\">Immunodéprimé</span> (formes ulcéro-hémorragiques, viscérales).</li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 27 — Prévention risques fœtaux</em></p>","frequence":1},{"id":"168-8","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les modalités du diagnostic d’un zona","contenu":"<div class=\"obj-callout success\"><strong>Définition.</strong> Le <span class=\"kw-def\">zona</span> est l'expression clinique de la <span class=\"kw-def\">réactivation du VZV</span> : une <span class=\"kw-def\">récurrence localisée</span>, <span class=\"kw-clinique\">unilatérale</span> et <span class=\"kw-clinique\">métamérique</span> (territoire d'une racine sensitive). Diagnostic <strong>clinique</strong>.</div>\n\n      <h4 class=\"kw-def\">Sémiologie typique</h4>\n      <table >\n        <thead><tr><th>Phase</th><th>Description</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-clinique\">Phase prodromique</span><br><em>(3–4 j avant l'<span class=\"kw-clinique\">éruption</span>)</em></td>\n            <td>Douleurs <span class=\"kw-clinique\">neuropathiques</span> (brûlures, coup de poignard, paroxysmes), paresthésies, troubles sensitifs, sur le territoire à venir ; <span class=\"kw-clinique\">radiculaires, unilatérales</span>.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\">Phase éruptive</span></td>\n            <td><span class=\"kw-clinique\">Placard</span> érythémateux → <span class=\"kw-clinique\">vésicules groupées en bouquet</span> à liquide clair puis trouble → érosions à <span class=\"kw-chiffre\">J5</span> → croûtes à <span class=\"kw-chiffre\">J7</span> → cicatrices dép<span class=\"kw-chiffre\">igm</span>entées à <span class=\"kw-chiffre\">J10</span> (souvent indélébiles).</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\">Topographie</span></td>\n            <td><strong>Unilatérale, monomérique</strong>, sans dépasser la <span class=\"kw-clinique\">ligne médiane</span>. Plus fréquent : <span class=\"kw-clinique\">intercostal / dorso-lombaire / sacré</span> (« demi-ceinture »). Formes céphaliques : <span class=\"kw-clinique\">zona ophtalmique</span> (V1), bucco-pharyngé, du ganglion géniculé.</td>\n          </tr>\n          <tr>\n            <td>Signes associés</td>\n            <td><span class=\"kw-clinique\">Syndrome <span class=\"kw-etio\">infectieux</span></span> discret (<span class=\"kw-chiffre\">38–38,5 °C</span>), <span class=\"kw-clinique\">adénopathie</span> satellite.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\"><strong>Drapeau étiologique.</strong> Devant un <span class=\"kw-clinique\">zona</span> du <span class=\"kw-clinique\">sujet jeune (&lt; 50 ans)</span> ou un zona étendu / atypique, rechercher une <span class=\"kw-alerte\">immunodépression</span> : <span class=\"kw-bio\">sérologie VIH</span>, <span class=\"kw-bio\">NFS</span> (hémopathie type LLC).</div>\n\n      <h4 class=\"kw-def\">Examens complémentaires</h4>\n      <ul>\n        <li>Diagnostic <strong>avant tout clinique</strong>. La confirmation par <span class=\"kw-bio\">PCR VZV</span> (écouvillonnage du contenu vésiculaire) ne se justifie que devant une <span class=\"kw-clinique\">forme sévère, compliquée ou atypique</span>, ou en cas de nécessité de certitude (femme enceinte).</li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 169 — <span class=\"kw-etio\">VIH</span></em></p>","frequence":6},{"id":"168-9","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les modalités du diagnostic des principales complications du zona (kératite, douleurs post-zostériennes, neurologiques)","contenu":"<div class=\"callout callout-warn\"><strong>Trois complications à connaître :</strong> le <span class=\"kw-alerte\">zona ophtalmique et sa kératite</span>, <span class=\"kw-clinique\">les</span> <span class=\"kw-alerte\">douleurs (algies) post-zostériennes</span>, et les <span class=\"kw-alerte\">complications neurologiques</span>.</div>\n\n      <h4 class=\"kw-def\">1 · <span class=\"kw-clinique\">Zona</span> ophtalmique (branche V1 du trijumeau) et kératite zostérienne</h4>\n      <ul>\n        <li>Plus fréquent chez le <span class=\"kw-etio\">sujet âgé</span> (&gt;<span class=\"kw-chiffre\"> 50 ans</span>). <span class=\"kw-clinique\">Éruption</span> sur une branche de V1 (frontale, lacrymale, <span class=\"kw-clinique\">nasale externe</span>).</li>\n        <li><span class=\"kw-alerte\">Signe de Hutchinson</span> (atteinte de la branche nasale externe) → risque oculaire accru.</li>\n        <li><span class=\"kw-clinique\">Kératite zostérienne</span> : kératite superficielle, test à la <span class=\"kw-bio\">fluorescéine</span> = ulcérations dendritiformes ; complications : kératite stromale, <span class=\"kw-alerte\">kératite neurotrophique/neuroparalytique</span> (anesthésie cornéenne séquellaire), uvéite antérieure (iridocyclite).</li>\n        <li>Risque : séquelles visuelles définitives, perte anatomique de l'œil.</li>\n      </ul>\n\n      <h4 class=\"kw-def\">2 · Algies post-zostériennes</h4>\n      <ul>\n        <li>Douleurs persistant <span class=\"kw-chiffre\">&gt; 1 mois</span> après le <span class=\"kw-clinique\">zona</span> ; disparaissent habituellement vers <span class=\"kw-chiffre\">6 mois</span> mais peuvent être définitives et invalidantes.</li>\n        <li><span class=\"kw-def\">Facteurs de risque</span> : <span class=\"kw-clinique\">âge &gt; 50 ans</span>, douleurs intenses en phase aiguë, troubles sensitifs initiaux importants, localisation céphalique, sévérité des lésions.</li>\n      </ul>\n\n      <h4 class=\"kw-def\">3 · Complications neurologiques et formes graves</h4>\n      <ul>\n        <li>Atteinte <span class=\"kw-clinique\">motrice</span> dans le territoire du <span class=\"kw-clinique\">zona</span>, <span class=\"kw-alerte\">myélite</span>, <span class=\"kw-alerte\">encéphalite</span> (parfois sans <span class=\"kw-clinique\">éruption</span>).</li>\n        <li>Immunodéprimé : extension <span class=\"kw-alerte\">bilatérale / multi-métamérique</span>, aspect <span class=\"kw-alerte\">ulcéro-hémorragique et nécrotique</span>, <span class=\"kw-clinique\">zona</span> « généralisé » (varicelliforme), atteintes viscérales.</li>\n        <li>Surinfections bactériennes (grattage).</li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 83 — Infection et inflammations occulaires</em></p>","frequence":0},{"id":"168-10","rang":"A","rubrique":"Contenu multimédia","titre":"Photographie de lésions de varicelle","contenu":"<div class=\"obj-callout success\"><strong>Sémiologie à reconnaître sur une photo.</strong> <span class=\"kw-clinique\">Éruption</span> <span class=\"kw-clinique\">vésiculeuse</span> diffuse, prédominant au tronc et au visage, faite de lésions d'<span class=\"kw-clinique\">âges différents</span> (signe pathognomonique).</div>\n\n      <ul>\n        <li><span class=\"kw-clinique\">Vésicule</span> typique = « <span class=\"kw-clinique\">goutte de rosée sur peau saine</span> » : vésicule à <span class=\"kw-clinique\">contenu clair</span> bordée d'une <span class=\"kw-clinique\">auréole érythémateuse</span>.</li>\n        <li>Coexistence sur la même zone de <span class=\"kw-clinique\">macules</span>, <span class=\"kw-clinique\">vésicules claires</span>, <span class=\"kw-clinique\">vésicules troubles ombiliquées</span> et <span class=\"kw-clinique\">croûtes</span> (poussées successives).</li>\n        <li>Topographie <span class=\"kw-clinique\">descendante</span> (cuir chevelu → face → tronc) ; respecte <span class=\"kw-clinique\">paumes et plantes</span> ; énanthème buccal possible.</li>\n      </ul>\n\n      <!-- TODO Kevin : déposer une photographie clinique de varicelle dans assets/images/168/ — pas de photo clinique exploitable dans le dossier source (seuls schémas d'histoire naturelle), ni dans IMAGERIE A CONNAITRE.pdf (banque radiologique). -->","frequence":1},{"id":"168-11","rang":"A","rubrique":"Contenu multimédia","titre":"Photographie d’une primo infection génitale HSV","contenu":"<div class=\"obj-callout success\"><strong>Sémiologie à reconnaître.</strong> <span class=\"kw-clinique\">Vulvovaginite aiguë brutale</span> (femme) ou balanite (homme), très <span class=\"kw-alerte\">douloureuse</span>, faite de <span class=\"kw-clinique\">vésicules</span> fugaces et surtout d'<span class=\"kw-clinique\">érosions arrondies / polycycliques</span> à fond <span class=\"kw-etio\">inflammatoire</span>.</div>\n\n      <ul>\n        <li>Muqueuse <span class=\"kw-clinique\">tuméfiée, œdémateuse</span> ; érosions multiples coalescentes pouvant déborder vers l'anus.</li>\n        <li>Contexte : tableau pseudo-grippal, <span class=\"kw-clinique\">adénopathies inguinales</span> sensibles, parfois <span class=\"kw-alerte\">rétention urinaire</span> (<span class=\"kw-alerte\">signe de gravité</span>).</li>\n        <li>Chez l'homme : balanite œdémateuse, vésicules du fourreau / scrotum.</li>\n      </ul>\n\n      <div class=\"callout callout-warn\"><strong>Réflexe <span class=\"kw-clinique\">IST</span>.</strong> Toute <span class=\"kw-clinique\">primo-infection</span> génitale <span class=\"kw-etio\">HSV</span> impose le <span class=\"kw-bio\">dépistage des IST</span> associées et une <span class=\"kw-bio\">sérologie VIH</span> systématique.</div>\n\n      <!-- TODO Kevin : déposer une photographie clinique d'herpès génital dans assets/images/168/ — absente du dossier source et de IMAGERIE A CONNAITRE.pdf. -->\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 162 — <span class=\"kw-clinique\">IST</span> · 169 — <span class=\"kw-etio\">VIH</span></em></p>","frequence":1},{"id":"168-12","rang":"A","rubrique":"Contenu multimédia","titre":"Photographie d’un herpès labial","contenu":"<div class=\"obj-callout success\"><strong>Sémiologie à reconnaître.</strong> Le classique « <span class=\"kw-clinique\">bouton de fièvre</span> » : <span class=\"kw-clinique\">bouquet de vésicules</span> unilatéral à la <span class=\"kw-clinique\">jonction cutanéo-muqueuse des lèvres</span>, sur fond érythémateux.</div>\n\n      <ul>\n        <li>Précédé de <span class=\"kw-clinique\">prodromes</span> (picotements, cuisson) ; topographie <span class=\"kw-clinique\">stéréotypée</span> et récidivante chez un même patient.</li>\n        <li><span class=\"kw-clinique\">Évolution</span> : vésicules → érosions → <span class=\"kw-clinique\">croûtes</span> → cicatrisation en quelques jours.</li>\n        <li>Récurrence banale : <strong>pas d'indication à un traitement <span class=\"kw-ttt\">antiviral</span></strong> dans la forme labiale simple.</li>\n      </ul>\n\n      <!-- TODO Kevin : déposer une photographie clinique d'herpès labial dans assets/images/168/ — absente du dossier source et de IMAGERIE A CONNAITRE.pdf. -->","frequence":0},{"id":"168-13","rang":"A","rubrique":"Contenu multimédia","titre":"Photographie d’un zona thoracique ; photographie d’un zona du visage","contenu":"<table >\n        <thead><tr><th>Localisation</th><th>Sémiologie sur la photo</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\">Zona thoracique</span><br><em>(intercostal)</em></td>\n            <td><span class=\"kw-clinique\">Éruption</span> <span class=\"kw-clinique\">vésiculeuse en bouquet</span> disposée en <span class=\"kw-clinique\">bande / demi-ceinture</span>, <span class=\"kw-clinique\">unilatérale</span>, <span class=\"kw-clinique\">métamérique</span>, s'arrêtant à la <span class=\"kw-clinique\">ligne médiane</span>.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Zona du visage</span><br><em>(ophtalmique V1)</em></td>\n            <td><span class=\"kw-clinique\">Éruption</span> sur le territoire du <span class=\"kw-clinique\">nerf ophtalmique V1</span> : front, paupière supérieure, racine du nez. Atteinte de l'aile / pointe du nez = <span class=\"kw-alerte\">signe de Hutchinson</span> (alerte oculaire).</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\"><strong>Point clé visuel.</strong> Ce qui signe le <span class=\"kw-clinique\">zona</span> sur une photo = la <span class=\"kw-clinique\">distribution métamérique unilatérale</span> qui ne franchit pas la ligne médiane, contrairement à la varicelle (diffuse).</div>\n\n      <!-- TODO Kevin : déposer les photographies cliniques (zona thoracique + zona du visage) dans assets/images/168/ — absentes du dossier source et de IMAGERIE A CONNAITRE.pdf. -->","frequence":3},{"id":"168-14","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître l’indication des PCR virales dans le diagnostic des infections à herpès virus","contenu":"<div class=\"obj-callout success\"><strong>La <span class=\"kw-bio\">PCR</span> est la technique de référence</strong> du diagnostic virologique direct des herpès virus : elle a <strong>remplacé la culture</strong>, est très <span class=\"kw-bio\">sensible et spécifique</span>, avec un résultat rapide (&lt;<span class=\"kw-chiffre\"> 24 h</span>).</div>\n\n      <div class=\"callout callout-info\"><strong>Rappel.</strong> Dans <span class=\"kw-clinique\">les</span> formes typiques sur <span class=\"kw-def\">terrain</span> non à risque, le diagnostic reste <strong>clinique</strong> : la <span class=\"kw-bio\">PCR</span> n'est <span class=\"kw-alerte\">pas systématique</span>.</div>\n\n      <h4 class=\"kw-def\">Indications principales de la <span class=\"kw-bio\">PCR</span></h4>\n      <table >\n        <thead><tr><th>Situation</th><th>Prélèvement</th></tr></thead>\n        <tbody>\n          <tr><td>Formes <span class=\"kw-clinique\">atypiques</span> ou <span class=\"kw-clinique\">résistantes</span> au traitement</td><td><span class=\"kw-bio\">PCR</span> sur écouvillonnage de <span class=\"kw-clinique\">vésicule</span> récente.</td></tr>\n          <tr><td><span class=\"kw-def\">Terrain</span> à risque / <span class=\"kw-alerte\">immunodéprimé</span>, formes graves</td><td><span class=\"kw-bio\">PCR</span> sur <span class=\"kw-clinique\">lésion</span> ± liquides biologiques.</td></tr>\n          <tr><td><span class=\"kw-alerte\">Méningo-encéphalite herpétique</span></td><td><span class=\"kw-bio\">PCR HSV dans le LCR</span> (examen clé du diagnostic).</td></tr>\n          <tr><td>Suspicion d'<span class=\"kw-alerte\">herpès néonatal</span></td><td><span class=\"kw-bio\">PCR</span> dans le <span class=\"kw-bio\">sang et le LCR</span> (+ dosage interféron α).</td></tr>\n          <tr><td>Diagnostic de certitude (ex. <span class=\"kw-etio\">femme enceinte</span>), confirmation <span class=\"kw-etio\">VZV</span></td><td><span class=\"kw-bio\">PCR</span> <span class=\"kw-etio\">VZV</span> sur contenu vésiculaire.</td></tr>\n        </tbody>\n      </table>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 151 — <span class=\"kw-clinique\">Méningite</span> - méningoencéphalite</em></p>","frequence":0},{"id":"168-15","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principes du traitement d’une infection à HSV et à VZV","contenu":"<div class=\"obj-callout success\"><strong>Principe général.</strong> <span class=\"kw-clinique\">Les</span> antiviraux anti-herpès sont <span class=\"kw-def\">virostatiques</span> : ils contrôlent une <span class=\"kw-clinique\">primo-infection</span> ou une réactivation symptomatique mais <strong>n'éradiquent pas le virus latent</strong> (risque de récidive à l'arrêt). Molécule pivot = l'<span class=\"kw-ttt\">aciclovir</span> (inhibe l'ADN polymérase <span class=\"kw-etio\">virale</span> après phosphorylation dans les cellules infectées).</div>\n\n      <h4 class=\"kw-def\">Molécules</h4>\n      <ul>\n        <li><span class=\"kw-ttt\">Aciclovir</span> : forme active, surtout <strong>voie IV</strong> (atteintes graves / viscérales).</li>\n        <li><span class=\"kw-ttt\">Valaciclovir</span> : prodrogue de l'<span class=\"kw-ttt\">aciclovir</span>, <strong>voie orale</strong> (meilleure biodisponibilité). <span class=\"kw-ttt\">Famciclovir</span> (prodrogue du penciclovir) PO.</li>\n        <li><span class=\"kw-ttt\">Foscarnet</span> IV : formes <span class=\"kw-clinique\">résistantes</span> à l'<span class=\"kw-ttt\">aciclovir</span> (immunodéprimé).</li>\n        <li>Pour le <span class=\"kw-etio\">CMV</span> de l'immunodéprimé : <span class=\"kw-ttt\">ganciclovir</span> / <span class=\"kw-ttt\">valganciclovir</span> / foscarnet. (<span class=\"kw-etio\">EBV</span> : pas d'<span class=\"kw-ttt\">antiviral</span>.)</li>\n      </ul>\n\n      <h4 class=\"kw-def\">Indications selon le tableau (<span class=\"kw-etio\">HSV</span>)</h4>\n      <table >\n        <thead><tr><th>Tableau</th><th>Traitement</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-clinique\">Herpès labial / orofacial</span> (récurrence simple)</td><td><strong>Pas d'<span class=\"kw-ttt\">antiviral</span></strong> en règle. <span class=\"kw-clinique\">Primo-infection</span> sévère : <span class=\"kw-ttt\">aciclovir</span> PO (ou IV si troubles de déglutition).</td></tr>\n          <tr><td><span class=\"kw-clinique\">Herpès génital</span></td><td><span class=\"kw-ttt\">Aciclovir PO ou valaciclovir PO</span> <span class=\"kw-chiffre\">5 j</span> ; formes sévères (rétention d'urine, douleurs intenses) : <span class=\"kw-ttt\">aciclovir IV</span> <span class=\"kw-chiffre\">10 j</span>.</td></tr>\n          <tr><td><span class=\"kw-alerte\">Herpès néonatal</span></td><td><span class=\"kw-ttt\">Aciclovir IV</span> : <span class=\"kw-chiffre\">14 j</span> (forme localisée) à <span class=\"kw-chiffre\">21 j</span> (forme neuro/disséminée).</td></tr>\n          <tr><td><span class=\"kw-alerte\">Méningo-encéphalite herpétique</span></td><td><span class=\"kw-ttt\">Aciclovir IV</span> <span class=\"kw-chiffre\">10 j</span>, en <strong><span class=\"kw-alerte\">urgence</span></strong> et de façon probabiliste.</td></tr>\n        </tbody>\n      </table>\n\n      <h4 class=\"kw-def\">Prévention des récurrences (<span class=\"kw-etio\">HSV</span>)</h4>\n      <ul>\n        <li>Indication : <span class=\"kw-chiffre\">≥ 6 récurrences/an</span> (génital ou orofacial) et/ou formes compliquées.</li>\n        <li><span class=\"kw-ttt\">Valaciclovir</span> (ou <span class=\"kw-ttt\">aciclovir</span>) PO quotidien au long cours <span class=\"kw-chiffre\">6–12 mois</span> puis <span class=\"kw-def\">réévaluation</span>. Ne permet <strong>pas</strong> l'éradication.</li>\n      </ul>\n\n      <h4 class=\"kw-def\">Particularités <span class=\"kw-etio\">VZV</span></h4>\n      <ul>\n        <li><strong>Varicelle bénigne de l'enfant :</strong> traitement <span class=\"kw-clinique\">symptomatique</span> (<span class=\"kw-ttt\">paracétamol</span>, antihistaminique, soins cutanés), <strong>pas d'<span class=\"kw-ttt\">antiviral</span></strong>.</li>\n        <li><strong>Varicelle grave / à risque :</strong> <span class=\"kw-ttt\">aciclovir IV</span> <span class=\"kw-chiffre\">10 j</span> si immunodéprimé, complication viscérale, nouveau-né, ou varicelle de la <span class=\"kw-etio\">femme enceinte</span> en péri-partum.</li>\n        <li><strong><span class=\"kw-clinique\">Zona</span> :</strong> <span class=\"kw-ttt\">antiviral</span> PO (<span class=\"kw-ttt\">valaciclovir</span> / famciclovir <span class=\"kw-chiffre\">7 j</span>) à débuter <span class=\"kw-alerte\">dans les 72 h</span> si &gt;<span class=\"kw-chiffre\"> 50 ans</span>, douleurs intenses, zona étendu ou <span class=\"kw-clinique\">ophtalmique</span> ; <span class=\"kw-ttt\">aciclovir IV</span> <span class=\"kw-chiffre\">7–10 j</span> si immunodéprimé. <span class=\"kw-ci\">Pas de corticothérapie générale</span>.</li>\n        <li><strong>Algies post-zostériennes :</strong>\n          <ul>\n            <li><span class=\"kw-ttt\">Antalgiques</span> à visée <span class=\"kw-clinique\">neuropathique</span> : <span class=\"kw-ttt\">amitriptyline</span>, <span class=\"kw-ttt\">gabapentine</span> (AMM) ; <span class=\"kw-ttt\">prégabaline</span>, <span class=\"kw-ttt\">carbamazépine</span> (hors AMM).</li>\n            <li>Topiques : <span class=\"kw-ttt\">emplâtre de lidocaïne</span> (<span class=\"kw-chiffre\">≤ 12 h</span>/j), <span class=\"kw-ttt\">capsaïcine</span> locale.</li>\n          </ul>\n        </li>\n      </ul>\n\n      <div class=\"callout callout-warn\"><strong>Femme enceinte exposée à la varicelle.</strong> Antécédent de varicelle ou <span class=\"kw-chiffre\">IgG</span> + → rien. Sinon (non immunisée) : si <span class=\"kw-def\">contact</span> <span class=\"kw-chiffre\">≤ 96 h</span> → <span class=\"kw-ttt\">immunoglobulines spécifiques anti-VZV</span> ; si contact &gt;<span class=\"kw-chiffre\"> 96 h</span> → pas de traitement spécifique.</div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 151 — <span class=\"kw-clinique\">Méningite</span> - méningoencéphalite · 27 — Prévention risques fœtaux</em></p>","frequence":3},{"id":"168-16","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principes de la prise en charge des manifestations ophtalmologiques d’un HSV","contenu":"<div class=\"obj-callout success\"><strong>La kératite herpétique</strong> est une atteinte <span class=\"kw-clinique\">unilatérale</span> : œil rouge, douleur, BAV variable, larmoiement, photophobie ; lésions vésiculeuses palpébrales. Diagnostic au <span class=\"kw-bio\">test à la fluorescéine</span> : <span class=\"kw-clinique\">ulcère dendritique</span> « en feuille de fougère » (forme typique) ou « en carte de géographie ».</div>\n\n      <div class=\"callout callout-danger\"><strong><span class=\"kw-ci\">Contre-indication</span> capitale.</strong> La kératite herpétique est une <span class=\"kw-ci\">contre-indication absolue à la corticothérapie locale</span> (et aux anesthésiques locaux) : leur usage à l'aveugle sur un œil rouge peut entraîner une <span class=\"kw-alerte\">perforation cornéenne</span>. → Devant tout œil <span class=\"kw-etio\">inflammatoire</span>, écarter une kératite herpétique avant tout collyre <span class=\"kw-ttt\">corticoïde</span>.</div>\n\n      <h4 class=\"kw-def\">Traitement</h4>\n      <ul>\n        <li><span class=\"kw-ttt\">Antiviral</span> par voie <span class=\"kw-clinique\">générale</span> (<span class=\"kw-ttt\">valaciclovir</span> / <span class=\"kw-ttt\">aciclovir</span> PO) ± débridement ; ou antiviral <span class=\"kw-clinique\">topique</span> (pommade <span class=\"kw-ttt\">aciclovir</span>, gel <span class=\"kw-ttt\">ganciclovir</span>, collyre trifluridine).</li>\n        <li>Formes profondes — <span class=\"kw-alerte\">kératite stromale, uvéite, nécrose rétinienne</span> : association <span class=\"kw-ttt\">aciclovir IV + topique</span>, avis ophtalmologique.</li>\n        <li>La <span class=\"kw-ttt\">corticothérapie</span> locale n'est justifiée que dans des situations précises (kératite stromale immunologique, uvéite antérieure) et <strong>après avis ophtalmologique</strong>.</li>\n        <li>Récidives fréquentes → <span class=\"kw-ttt\">prophylaxie antivirale orale</span> si &gt; 6 récurrences/an.</li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 83 — Infection et inflammations occulaires</em></p>","frequence":0},{"id":"168-17","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principales toxicités des traitements actifs sur HSV et VZV","contenu":"<div class=\"callout callout-warn\"><strong>Toxicité dominante de l'<span class=\"kw-ttt\">aciclovir</span> / <span class=\"kw-ttt\">valaciclovir</span> : rénale et neurologique.</strong></div>\n\n      <table >\n        <thead><tr><th>Molécule</th><th>Toxicités à connaître</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-ttt\">Aciclovir</span> / <span class=\"kw-ttt\">Valaciclovir</span></td>\n            <td><span class=\"kw-alerte\">Tubulopathie par cristallurie</span> → <span class=\"kw-alerte\">insuffisance rénale aiguë</span> : <strong>hydratation ++</strong> et adaptation à la fonction rénale impératives.<br><span class=\"kw-alerte\">Encéphalopathie</span> (confusion, troubles neuro), surtout si surdosage / <span class=\"kw-ci\">insuffisance rénale</span>.<br><span class=\"kw-clinique\">Résistances virales</span> possibles en cas d'utilisation prolongée (immunodéprimé).</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-ttt\">Foscarnet</span> (anti-résistant, <span class=\"kw-etio\">CMV</span>)</td>\n            <td>Néphrotoxicité, troubles ioniques (<span class=\"kw-bio\">calcémie</span> / <span class=\"kw-bio\">phosphorémie</span>).</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-ttt\">Ganciclovir</span> / <span class=\"kw-ttt\">Valganciclovir</span> (<span class=\"kw-etio\">CMV</span>)</td>\n            <td>Toxicité <span class=\"kw-bio\">hématologique</span> (neutropénie, thrombopénie).</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\"><strong>Réflexe.</strong> Avant et pendant un traitement par <span class=\"kw-ttt\">aciclovir</span>/<span class=\"kw-ttt\">valaciclovir</span> : <span class=\"kw-bio\">fonction rénale</span> et <strong>hydratation</strong> ; surveiller l'apparition de signes neurologiques.</div>","frequence":0},{"id":"168-18","rang":"B","rubrique":"Prise en charge","titre":"Connaître les indications du vaccin contre la varicelle et du vaccin contre le zona","contenu":"<div class=\"callout callout-info\"><strong>À retenir.</strong> Deux vaccins <span class=\"kw-def\">vivants atténués</span> issus de la <strong>même souche</strong> (celui du <span class=\"kw-clinique\">zona</span> est plus dosé) → <span class=\"kw-ci\">contre-indiqués chez l'immunodéprimé et la femme enceinte</span>. Il n'existe <strong>pas</strong> de vaccin contre <span class=\"kw-etio\">HSV</span> ni contre le CMV.</div>\n\n      <table >\n        <thead><tr><th></th><th>Vaccin varicelle</th><th>Vaccin zona</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Type</strong></td>\n            <td><span class=\"kw-ttt\">Vivant atténué</span></td>\n            <td><span class=\"kw-ttt\">Vivant atténué</span> (même souche, plus dosé)</td>\n          </tr>\n          <tr>\n            <td><strong>Schéma</strong></td>\n            <td><span class=\"kw-chiffre\">2 doses</span> (espacées <span class=\"kw-chiffre\">1–2 mois</span>), à partir de <span class=\"kw-chiffre\">1 an</span></td>\n            <td><span class=\"kw-chiffre\">1 dose</span></td>\n          </tr>\n          <tr>\n            <td><strong>Cible / indications</strong></td>\n            <td>Non au <span class=\"kw-ttt\">calendrier vaccinal</span> systématique. Recommandé : <span class=\"kw-clinique\">ado 12–18 ans</span> non immunisé ; <span class=\"kw-etio\">femme en âge de procréer</span> non immunisée (test de <span class=\"kw-ci\">grossesse</span> négatif + contraception) ; sujet en <span class=\"kw-clinique\">contact avec un immunodéprimé</span> ; <span class=\"kw-clinique\">professionnels de santé / petite enfance</span> ; <span class=\"kw-clinique\">post-exposition</span> chez l'adulte non immunisé (&lt;<span class=\"kw-chiffre\"> 72 h</span>).</td>\n            <td><span class=\"kw-clinique\">Adultes de 65 à 74 ans révolus</span>, y compris ceux ayant déjà fait un <span class=\"kw-clinique\">zona</span>.</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-ci\">Contre-indications</span></strong></td>\n            <td><span class=\"kw-ci\">Femme enceinte</span>, <span class=\"kw-ci\">immunodéprimé</span></td>\n            <td><span class=\"kw-ci\">Personnes immunodéprimées</span></td>\n          </tr>\n          <tr>\n            <td><strong>Efficacité</strong></td>\n            <td><span class=\"kw-chiffre\">65–100 %</span> de couverture, durable mais <strong>non définitive</strong></td>\n            <td>≈<span class=\"kw-chiffre\"> 70 %</span>, durable mais non définitive</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\"><strong>Pas de <span class=\"kw-ttt\">vaccination</span> de l'enfant en population générale</strong> contre la varicelle (sauf cas particulier, ex. enfant candidat à une greffe d'organe, séronégatif).</div>","frequence":0}],"astuces":[],"strategie":{"urgence":"<p><strong>Fenêtre antivirale du <span class=\"kw-clinique\">zona</span> :</strong> <span class=\"kw-ttt\">antiviral</span> PO à débuter dans <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">72 h</span> suivant le début de l'<span class=\"kw-clinique\">éruption</span> pour <span class=\"kw-ttt\">prévenir les algies post-zostériennes</span> et les complications oculaires<br><strong>Herpès néonatal suspecté :</strong> <span class=\"kw-ttt\">aciclovir IV</span> probabiliste <span class=\"kw-alerte\">sans attendre la confirmation virologique</span><br><strong><span class=\"kw-clinique\">Méningo-encéphalite</span> herpétique :</strong> <span class=\"kw-alerte\">urgence vitale</span>, <span class=\"kw-ttt\">aciclovir IV</span> <span class=\"kw-chiffre\">10 jours</span><br><strong>Varicelle de la femme enceinte :</strong> <span class=\"kw-ttt\">aciclovir IV</span> si éruption dans les <span class=\"kw-chiffre\">8 à 10 jours avant l'accouchement</span></p>","hospit":"<p><strong>Ambulatoire :</strong> <span class=\"kw-clinique\">varicelle commune de l'enfant</span> et <span class=\"kw-clinique\">herpès cutanéo-muqueux non compliqué</span>, prise en charge <span class=\"kw-ttt\">symptomatique</span><br><strong><span class=\"kw-alerte\">Hospitalisation</span> + <span class=\"kw-ttt\">aciclovir</span> IV :</strong> <span class=\"kw-alerte\">formes graves ou compliquées</span> — <span class=\"kw-etio\">nouveau-né</span>, <span class=\"kw-etio\">immunodéprimé</span>, <span class=\"kw-etio\">complication viscérale</span> (pneumopathie, hépatite), <span class=\"kw-etio\">femme enceinte proche du terme</span><br><strong>Gingivostomatite :</strong> hospitalisation si <span class=\"kw-alerte\">alimentation impossible</span> (réhydratation IV)<br><strong><span class=\"kw-def\">Isolement</span> :</strong> précautions <span class=\"kw-ttt\">contact</span> et <span class=\"kw-ttt\">air</span> en cas d'hospitalisation pour le <span class=\"kw-etio\">VZV</span></p>","redflags":"<ul><li><span class=\"kw-alerte\">Pneumopathie varicelleuse</span> : <span class=\"kw-clinique\">toux</span>, dyspnée, hémoptysies — responsable de <span class=\"kw-chiffre\">30 %</span> des décès de la varicelle de l'adulte</li><li><span class=\"kw-alerte\">Surinfection cutanée grave</span> : <span class=\"kw-etio\">dermohypodermite</span>, <span class=\"kw-etio\">fasciite nécrosante</span> (favorisée par <span class=\"kw-clinique\">les</span> <span class=\"kw-ci\">AINS</span>)</li><li><span class=\"kw-alerte\">Syndrome de Reye</span> : encéphalopathie et <span class=\"kw-etio\">stéatose</span> hépatique liées à l'<span class=\"kw-ci\">aspirine</span></li><li><span class=\"kw-alerte\">Zona ophtalmique</span> (V1) : risque de <span class=\"kw-alerte\">cécité</span>, avis ophtalmologique</li><li><span class=\"kw-alerte\">Herpès néonatal</span> et <span class=\"kw-alerte\">méningo-encéphalite herpétique</span> : <span class=\"kw-alerte\">pronostic vital</span> et neurologique engagé</li><li><span class=\"kw-etio\">Atteinte viscérale</span> chez l'<span class=\"kw-etio\">immunodéprimé</span> : formes <span class=\"kw-clinique\">nécrotiques</span>, extensives, multimétamériques</li><li><span class=\"kw-alerte\">Syndrome de Kaposi-Juliusberg</span> (<span class=\"kw-clinique\">eczéma</span> herpeticum) sur dermatite <span class=\"kw-etio\">atopique</span></li><li><span class=\"kw-clinique\">Rétention urinaire</span> au cours d'un herpès génital (<span class=\"kw-alerte\">signe de gravité</span>)</li><li><span class=\"kw-clinique\">Dysphagie</span> avec <span class=\"kw-clinique\">déshydratation</span> lors d'une gingivostomatite herpétique</li></ul>","principes":"<p>Traitement <span class=\"kw-ttt\">virostatique</span> (<span class=\"kw-ttt\">aciclovir</span> et dérivés) : il contrôle la <span class=\"kw-clinique\">primo-infection</span> ou la réactivation mais <span class=\"kw-alerte\">n'éradique pas le virus latent</span> (récidive possible à l'arrêt). <span class=\"kw-alerte\">Diagnostic clinique</span> dans la majorité des cas.</p><p><strong>Molécules antivirales</strong></p><p><span class=\"kw-alerte\">Traitements locaux inefficaces</span> sur l'herpès cutanéo-muqueux</p><ul><li><span class=\"kw-ttt\">Aciclovir</span> : forme active, surtout voie <span class=\"kw-ttt\">IV</span> — inhibe l'ADN polymérase <span class=\"kw-etio\">virale</span></li><li><span class=\"kw-ttt\">Valaciclovir</span> PO : prodrogue de l'<span class=\"kw-ttt\">aciclovir</span>, meilleure biodisponibilité</li><li><span class=\"kw-ttt\">Famciclovir</span> PO : alternative orale (prodrogue du penciclovir)</li><li><span class=\"kw-ttt\">Foscarnet</span> IV : formes <span class=\"kw-etio\">résistantes à l'aciclovir</span> (immunodéprimé)</li></ul><p><strong>Herpès orofacial / labial</strong></p><ul><li><span class=\"kw-clinique\">Primo-infection</span> (gingivostomatite) : <span class=\"kw-ttt\">aciclovir</span> PO ou IV, <span class=\"kw-chiffre\">5 à 10 jours</span>, débuté < <span class=\"kw-chiffre\"><span class=\"kw-chiffre\">3 jours</span></span></li><li>Récurrence (bouton de <span class=\"kw-clinique\">fièvre</span>) : <span class=\"kw-alerte\">pas d'antiviral</span></li><li>Préventif si <span class=\"kw-chiffre\">≥ 6 récurrences/an</span> : <span class=\"kw-ttt\">valaciclovir</span> PO <span class=\"kw-chiffre\">6 à 12 mois</span></li></ul><p><strong>Herpès génital</strong></p><p><span class=\"kw-bio\">Sérologie VIH</span> et <span class=\"kw-ttt\">dépistage des IST</span> systématiques</p><ul><li><span class=\"kw-clinique\">Primo-infection</span> : <span class=\"kw-ttt\">valaciclovir</span> ou <span class=\"kw-ttt\">aciclovir</span> PO <span class=\"kw-chiffre\">5 jours</span></li><li>Forme sévère (<span class=\"kw-clinique\">rétention d'urines</span>, douleurs intenses) : <span class=\"kw-ttt\">aciclovir IV</span> <span class=\"kw-chiffre\">10 jours</span></li><li>Récurrence : traitement non systématique, le plus tôt possible</li></ul><p><strong>Varicelle</strong></p><ul><li>Forme bénigne de l'enfant : <span class=\"kw-ttt\">ambulatoire symptomatique</span> — <span class=\"kw-ttt\">paracétamol</span>, antihistaminique sédatif, <span class=\"kw-ttt\">chlorhexidine</span> aqueuse, ongles courts</li><li><span class=\"kw-ci\">Pas d'aspirine</span> (<span class=\"kw-alerte\">syndrome de Reye</span>) ni d'<span class=\"kw-ci\">AINS</span> (<span class=\"kw-alerte\">fasciite nécrosante</span>)</li><li><span class=\"kw-ci\">Pas de topiques</span> (talc, anesthésiques) : ils masquent la surinfection</li><li><span class=\"kw-ttt\">Aciclovir IV</span> si : nouveau-né, forme grave < <span class=\"kw-chiffre\"><span class=\"kw-chiffre\">1 an</span></span>, complication viscérale, immunodépression, femme enceinte proche du terme</li></ul><p><strong><span class=\"kw-clinique\">Zona</span></strong></p><p><span class=\"kw-ci\">Pas de corticothérapie générale</span> ; <span class=\"kw-ttt\">antalgiques</span> de <span class=\"kw-ttt\">palier 2-3</span> en phase aiguë</p><ul><li><span class=\"kw-ttt\">Antiviral</span> PO < <span class=\"kw-chiffre\"><span class=\"kw-chiffre\">72 h</span></span> si : <span class=\"kw-clinique\">> 50 ans</span>, douleurs intenses, <span class=\"kw-clinique\">zona</span> étendu, ou <span class=\"kw-alerte\">zona ophtalmique</span></li><li>Immunocompétent : <span class=\"kw-ttt\">valaciclovir</span> ou <span class=\"kw-ttt\">famciclovir</span> PO <span class=\"kw-chiffre\">7 jours</span></li><li>Immunodéprimé : <span class=\"kw-ttt\">aciclovir IV</span> <span class=\"kw-chiffre\">7 à 10 jours</span></li><li>Algies post-zostériennes : <span class=\"kw-ttt\">amitriptyline</span> ou <span class=\"kw-ttt\">gabapentine</span>, emplâtre de <span class=\"kw-ttt\">lidocaïne</span></li></ul>","suivi":"<p><strong>Tolérance des antiviraux :</strong> surveiller la <span class=\"kw-bio\">fonction rénale</span> sous <span class=\"kw-ttt\">aciclovir</span> (<span class=\"kw-alerte\">tubulopathie par cristallurie</span> → <span class=\"kw-ttt\">hydratation abondante</span>) et le <span class=\"kw-alerte\">risque d'encéphalopathie</span><br><strong>Algies post-zostériennes :</strong> douleurs persistant <span class=\"kw-chiffre\">> 1 mois</span> après le <span class=\"kw-clinique\">zona</span>, surtout si <span class=\"kw-clinique\">> 50 ans</span> — <span class=\"kw-def\">réévaluation</span> et <span class=\"kw-ttt\">antalgiques</span> neuropathiques<br><strong>Traitement préventif :</strong> réévaluation à <span class=\"kw-chiffre\">6 à 12 mois</span> en cas de <span class=\"kw-chiffre\">≥ 6 récurrences/an</span><br><strong>Résistances :</strong> émergence de souches <span class=\"kw-etio\">résistantes à l'aciclovir</span> chez l'immunodéprimé en cas d'usage prolongé</p>"},"liensGlobaux":[{"href":"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-168.pdf","label":"Collège (PILLY étudiant 2023) — item 168"},{"href":"https://www.cen-neurologie.fr/second-cycle/infections-a-herpes-virus-du-sujet-immunocompetent-infections-par-le-vih","label":"Collège de Neurologie (CEN) — Infections à herpès virus"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Infection à HSV ou VZV — Forme grave, terrain à risque ou atteinte viscérale ?","detail":"<h4>CAT — Traitement <span class=\"kw-ttt\">antiviral</span> d'une infection à <span class=\"kw-etio\">HSV</span> / VZV — Orientation thérapeutique selon la forme clinique et le <span class=\"kw-def\">terrain</span></h4>","branches":[{"to":"t-urgence","label":"Oui","color":"red"},{"to":"q-type","label":"Non","color":"green"}]},{"id":"t-urgence","kind":"terminal","label":"Hospitalisation + aciclovir IV — Urgence — sans attendre la confirmation","color":"red","detail":"<h4>Conduite</h4><ul><li><span class=\"kw-ttt\">Aciclovir IV</span> en <span class=\"kw-alerte\">urgence</span> et <span class=\"kw-ttt\">isolement</span> (précautions <span class=\"kw-def\">contact</span> / air pour le <span class=\"kw-etio\">VZV</span>)</li></ul><h4>Indications</h4><ul><li><span class=\"kw-alerte\">Méningo-encéphalite herpétique</span> : <span class=\"kw-ttt\">aciclovir</span> IV <span class=\"kw-chiffre\">10 jours</span></li><li><span class=\"kw-alerte\">Herpès néonatal</span> suspecté : IV probabiliste, sans attendre la <span class=\"kw-bio\">PCR</span></li><li><span class=\"kw-etio\">Immunodéprimé</span> ou <span class=\"kw-etio\">atteinte viscérale</span> (pneumopathie, hépatite)</li><li><span class=\"kw-etio\">Varicelle de la femme enceinte</span> proche du terme</li><li><span class=\"kw-alerte\">Syndrome de Kaposi-Juliusberg</span> (<span class=\"kw-clinique\">eczéma</span> herpeticum)</li></ul>"},{"id":"q-type","kind":"decision","label":"Quelle forme clinique ? — Patient immunocompétent, sans signe de gravité","branches":[{"to":"t-orofacial","label":"Herpès labial récurrent","color":"green"},{"to":"t-genital","label":"Herpès génital","color":"amber"},{"to":"t-varicelle","label":"Varicelle commune","color":"green"},{"to":"q-zona","label":"Zona","color":"blue"}]},{"id":"t-orofacial","kind":"terminal","label":"Herpès labial récurrent : abstention — Bouton de fièvre","color":"green","detail":"<h4>Traitement</h4><ul><li><span class=\"kw-alerte\">Pas d'antiviral</span> pour une récurrence simple</li><li>Préventif si <span class=\"kw-chiffre\">≥ 6 récurrences/an</span> : <span class=\"kw-ttt\">valaciclovir</span> PO <span class=\"kw-chiffre\">6 à 12 mois</span></li></ul><h4>Conduite</h4><ul><li><span class=\"kw-ttt\">Photoprotection</span> et éviction des facteurs déclenchants</li></ul>"},{"id":"t-genital","kind":"terminal","label":"Herpès génital : antiviral PO + dépistage IST","color":"amber","detail":"<h4>Traitement</h4><ul><li><span class=\"kw-clinique\">Primo-infection</span> : <span class=\"kw-ttt\">valaciclovir</span> ou <span class=\"kw-ttt\">aciclovir</span> PO <span class=\"kw-chiffre\">5 jours</span></li><li>Récurrence : non systématique, le plus tôt possible</li><li>Forme sévère (<span class=\"kw-clinique\">rétention d'urines</span>) : <span class=\"kw-ttt\">aciclovir IV</span> <span class=\"kw-chiffre\">10 jours</span></li></ul><h4>Conduite</h4><ul><li><span class=\"kw-bio\">Sérologie VIH</span> et <span class=\"kw-ttt\">dépistage des IST</span> systématiques</li></ul>"},{"id":"t-varicelle","kind":"terminal","label":"Varicelle commune : ambulatoire symptomatique","color":"green","detail":"<h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Paracétamol</span>, antihistaminique sédatif, <span class=\"kw-ttt\">chlorhexidine</span> aqueuse, ongles courts</li><li><span class=\"kw-alerte\">Pas d'antiviral</span> dans la forme bénigne</li></ul><h4><span class=\"kw-ci\">Contre-indications</span></h4><ul><li><span class=\"kw-ci\">Aspirine</span> (<span class=\"kw-alerte\">syndrome de Reye</span>)</li><li><span class=\"kw-ci\">AINS</span> (<span class=\"kw-alerte\">fasciite nécrosante</span>)</li><li><span class=\"kw-ci\">Topiques</span> (talc, anesthésiques) qui masquent la surinfection</li></ul>"},{"id":"q-zona","kind":"decision","label":"Zona : facteur de risque ? — Évaluer terrain, localisation et intensité des douleurs","branches":[{"to":"t-zona-grave","label":"Ophtalmique ou immunodéprimé","color":"red"},{"to":"t-zona-antiviral","label":"> 50 ans, douleurs intenses ou étendu","color":"amber"},{"to":"t-zona-simple","label":"< 50 ans, peu douloureux","color":"green"}]},{"id":"t-zona-grave","kind":"terminal","label":"Antiviral systématique ± avis spécialisé — Zona ophtalmique ou immunodéprimé","color":"red","detail":"<h4>Traitement</h4><ul><li><span class=\"kw-clinique\">Zona</span> ophtalmique : <span class=\"kw-ttt\">valaciclovir</span> PO < <span class=\"kw-chiffre\"><span class=\"kw-chiffre\">72 h</span></span> + <span class=\"kw-ttt\">pommade à l'aciclovir</span>, avis ophtalmologique</li><li>Immunodéprimé : <span class=\"kw-ttt\">aciclovir IV</span> <span class=\"kw-chiffre\">7 à 10 jours</span></li></ul><h4>Conduite</h4><ul><li>Risque de <span class=\"kw-alerte\">cécité</span> (<span class=\"kw-clinique\">zona</span> ophtalmique), de formes <span class=\"kw-etio\">nécrotiques / disséminées</span> (immunodéprimé)</li></ul>"},{"id":"t-zona-antiviral","kind":"terminal","label":"<span class=\"kw-ttt\">Antiviral</span> PO précoce (<span class=\"kw-chiffre\">< 72</span> h) — Prévention des algies post-zostériennes","color":"amber","detail":"<h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Valaciclovir</span> ou <span class=\"kw-ttt\">famciclovir</span> PO <span class=\"kw-chiffre\">7 jours</span>, débuté < <span class=\"kw-chiffre\"><span class=\"kw-chiffre\">72 h</span></span></li><li><span class=\"kw-ttt\">Antalgiques</span> de <span class=\"kw-ttt\">palier 2-3</span> en phase aiguë</li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li><span class=\"kw-clinique\">Algies post-zostériennes</span> : amitriptyline, <span class=\"kw-ttt\">gabapentine</span>, emplâtre de <span class=\"kw-ttt\">lidocaïne</span></li></ul>"},{"id":"t-zona-simple","kind":"terminal","label":"Traitement local + <span class=\"kw-ttt\">antalgiques</span> — <span class=\"kw-clinique\">Zona</span> < <span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>50</span> ans</span>, peu douloureux, non compliqué","color":"green","detail":"<h4>Traitement</h4><ul><li>Soins locaux (chlorhexidine aqueuse, ongles courts) et <span class=\"kw-ttt\">antalgiques</span></li><li><span class=\"kw-alerte\">Pas d'antiviral</span> systématique ; <span class=\"kw-ci\">pas de corticothérapie générale</span></li></ul>"}]},"cards":[{"i":"3e350c1d3402","n":168,"o":"168-1","u":"Epidémiologie","t":"Connaître les modes de transmissions pour l’herpès virus (HSV) et le virus varicelle-zona (VZV)","q":"Quel est le principal mode de transmission des virus herpès simplex (HSV-1 et HSV-2) ?","a":"<p>Le principal mode de transmission des virus herpès simplex (HSV) est le <strong>contact direct cutanéo-muqueux</strong>.</p>"},{"i":"9890240d81c8","n":168,"o":"168-1","u":"Epidémiologie","t":"Connaître les modes de transmissions pour l’herpès virus (HSV) et le virus varicelle-zona (VZV)","q":"Quels sont les modes de transmission du virus varicelle-zona (VZV) ?","a":"<ul><li>La transmission des VZV se fait par <strong>contact direct</strong> avec les lésions cutanéo-muqueuses.</li><li>Elle est également <strong>aérienne (respiratoire)</strong>, faisant de la varicelle la maladie éruptive la plus contagieuse, nécessitant des précautions de type AIR en milieu de soins.</li></ul>"},{"i":"dd991a2bbf9b","n":168,"o":"168-1","u":"Epidémiologie","t":"Connaître les modes de transmissions pour l’herpès virus (HSV) et le virus varicelle-zona (VZV)","q":"Quelle est la période de contagiosité de la varicelle et du zona ?","a":"<ul><li>La <strong>varicelle</strong> est contagieuse <strong>1 à 2 jours avant l'éruption</strong> et persiste <strong>jusqu'à ce que toutes les vésicules soient croûteuses (soit au moins 5 à 7 jours)</strong>.</li><li>Le <strong>zona</strong> est contagieux par <strong>contact direct</strong> avec les lésions (excrétion virale localisée).</li></ul>"},{"i":"e0f0e022a6a5","n":168,"o":"168-1","u":"Epidémiologie","t":"Connaître les modes de transmissions pour l’herpès virus (HSV) et le virus varicelle-zona (VZV)","q":"Quels sont les différents types de contact direct cutanéo-muqueux favorisant la transmission des HSV-1 et HSV-2 ?","a":"<ul><li>Pour HSV-1 : la <strong>salive</strong> et le <strong>baiser</strong>.</li><li>Pour HSV-2 : les <strong>rapports sexuels</strong>.</li><li>Pour HSV-1 et HSV-2 : le contact <strong>per-partum</strong> lors du passage dans la filière génitale, entraînant un herpès néonatal.</li></ul><p>Toute altération du revêtement épithélial (érosion, dermatose inflammatoire, rapport traumatisant) favorise cette transmission.</p>"},{"i":"64601157097c","n":168,"o":"168-10","u":"Contenu multimédia","t":"Photographie de lésions de varicelle","q":"Quelles sont les différentes morphologies lésionnelles que l'on peut retrouver simultanément en cas de varicelle ?","a":"<p>Sur la même zone cutanée, on peut observer une coexistence de :</p><ul><li><strong>Macules</strong></li><li><strong>Vésicules claires</strong></li><li>Vésicules troubles et <strong>ombiliquées</strong></li><li><strong>Croûtes</strong></li></ul><p>Ceci est dû aux poussées successives de l'éruption.</p>"},{"i":"aa9629e74bb3","n":168,"o":"168-10","u":"Contenu multimédia","t":"Photographie de lésions de varicelle","q":"Décrivez la topographie de l'éruption cutanée de la varicelle.","a":"<p>La topographie est <strong>descendante</strong>, débutant au <strong>cuir chevelu</strong>, puis touchant la <strong>face</strong> et le <strong>tronc</strong>. Les <strong>paumes et les plantes sont généralement respectées</strong>. Un <strong>énanthème buccal</strong> est également possible.</p>"},{"i":"e18d8978c87f","n":168,"o":"168-10","u":"Contenu multimédia","t":"Photographie de lésions de varicelle","q":"Comment se caractérise l'éruption cutanée d'une varicelle à l'inspection ?","a":"<p>L'éruption est <strong>vésiculeuse diffuse</strong>, prédominant au <strong>tronc et au visage</strong>, composée de lésions d'<strong>âges différents</strong>, ce qui est un signe pathognomonique de la varicelle.</p>"},{"i":"fb20c9fd983b","n":168,"o":"168-10","u":"Contenu multimédia","t":"Photographie de lésions de varicelle","q":"Quelle est la description sémiologique classique d'une vésicule de varicelle ?","a":"<p>Une vésicule typique de varicelle est décrite comme une « <strong>goutte de rosée sur peau saine</strong> ». Il s'agit d'une vésicule à <strong>contenu clair</strong>, bordée d'une <strong>auréole érythémateuse</strong>.</p>"},{"i":"0b17a2d48b25","n":168,"o":"168-11","u":"Contenu multimédia","t":"Photographie d’une primo infection génitale HSV","q":"Quels sont les signes cliniques locaux caractéristiques d'une primo-infection génitale à HSV chez la femme ?","a":"<p>La primo-infection génitale à HSV chez la femme se manifeste par une <strong>vulvovaginite aiguë</strong> d'apparition brutale et très douloureuse. On observe :</p><ul><li>Des <strong>vésicules fugaces</strong>.</li><li>Des <strong>érosions arrondies ou polycycliques</strong> à fond inflammatoire.</li><li>La muqueuse est <strong>tuméfiée et œdémateuse</strong>.</li><li>Des érosions multiples peuvent <strong>coalescer</strong> et déborder vers l'anus.</li></ul>"},{"i":"42362224d099","n":168,"o":"168-11","u":"Contenu multimédia","t":"Photographie d’une primo infection génitale HSV","q":"Quels sont les signes cliniques locaux caractéristiques d'une primo-infection génitale à HSV chez l'homme ?","a":"<p>Chez l'homme, la primo-infection génitale à HSV se traduit par une <strong>balanite œdémateuse</strong>. On peut également observer des <strong>vésicules situées sur le fourreau ou le scrotum</strong>.</p>"},{"i":"c57bd6f0283a","n":168,"o":"168-11","u":"Contenu multimédia","t":"Photographie d’une primo infection génitale HSV","q":"Quels sont les signes d'accompagnement systémiques et les éléments de gravité ou de prise en charge à rechercher devant une primo-infection génitale à HSV ?","a":"<p>Une primo-infection génitale à HSV peut s'accompagner d'un <strong>tableau pseudo-grippal</strong> et d'<strong>adénopathies inguinales sensibles</strong>.</p><p>La <strong>rétention urinaire</strong> est un <strong>signe de gravité</strong>.</p><p>Toute primo-infection génitale à HSV impose la réalisation systématique de :</p><ul><li>Un <strong>dépistage des IST associées</strong>.</li><li>Une <strong>sérologie VIH</strong>.</li></ul>"},{"i":"2d52a9d20da5","n":168,"o":"168-12","u":"Contenu multimédia","t":"Photographie d’un herpès labial","q":"Quels sont les signes prodromiques et la topographie typique de l'herpès labial ?","a":"<p>L'herpès labial est souvent précédé de <strong>prodromes</strong> tels que des <strong>picotements ou une sensation de cuisson</strong>. Sa topographie est <strong>stéréotypée et récidivante</strong> chez un même patient.</p>"},{"i":"99163127e82b","n":168,"o":"168-12","u":"Contenu multimédia","t":"Photographie d’un herpès labial","q":"Quelle est l'évolution typique des lésions d'herpès labial et la conduite à tenir en cas de forme simple ?","a":"<p>L'évolution des lésions d'herpès labial se fait en plusieurs étapes : <strong>vésicules</strong> puis <strong>érosions</strong>, suivies de <strong>croûtes</strong>, et enfin une <strong>cicatrisation en quelques jours</strong>. En cas de forme labiale simple, il s'agit d'une récurrence banale qui ne justifie <strong>pas de traitement antiviral</strong>.</p>"},{"i":"c4c470022a8d","n":168,"o":"168-12","u":"Contenu multimédia","t":"Photographie d’un herpès labial","q":"Comment se présente cliniquement un herpès labial, également appelé \"bouton de fièvre\" ?","a":"<p>Un herpès labial se caractérise par un <strong>bouquet de vésicules unilatéral</strong>, apparaissant à la <strong>jonction cutanéo-muqueuse des lèvres</strong>, sur un <strong>fond érythémateux</strong>.</p>"},{"i":"6758c10bfb58","n":168,"o":"168-13","u":"Contenu multimédia","t":"Photographie d’un zona thoracique ; photographie d’un zona du visage","q":"Quelle est la sémiologie dermatologique caractéristique d'un zona thoracique telle qu'observable sur une photographie ?","a":"<p>Un zona thoracique se manifeste par une <strong>éruption vésiculeuse en bouquet</strong>, disposée en <strong>bande ou demi-ceinture</strong>. Elle est typiquement <strong>unilatérale</strong>, <strong>métamérique</strong> et s'arrête strictement à la <strong>ligne médiane</strong>.</p>"},{"i":"b037f715c41c","n":168,"o":"168-13","u":"Contenu multimédia","t":"Photographie d’un zona thoracique ; photographie d’un zona du visage","q":"Quel est le critère sémiologique visuel essentiel permettant de différencier un zona d'une varicelle sur une photographie ?","a":"<p>Le signe visuel essentiel est la <strong>distribution métamérique unilatérale</strong> de l'éruption qui <strong>ne franchit pas la ligne médiane</strong>, contrairement à la varicelle qui est une éruption diffuse.</p>"},{"i":"c93e96524d76","n":168,"o":"168-13","u":"Contenu multimédia","t":"Photographie d’un zona thoracique ; photographie d’un zona du visage","q":"Quelle est la sémiologie dermatologique caractéristique d'un zona du visage, notamment ophtalmique V1, telle qu'observable sur une photographie ?","a":"<p>Un zona du visage, en particulier ophtalmique (V1), présente une éruption cutanée sur le territoire du <strong>nerf ophtalmique V1</strong>, incluant le <strong>front</strong>, la <strong>paupière supérieure</strong> et la <strong>racine du nez</strong>. La présence d'une atteinte de l'aile ou de la pointe du nez correspond au <strong>signe de Hutchinson</strong>, alertant sur un risque d'atteinte oculaire.</p>"},{"i":"5211044856fa","n":168,"o":"168-15","u":"Prise en charge","t":"Connaître les principes du traitement d’une infection à HSV et à VZV","q":"Quels sont les traitements spécifiques d'une infection à HSV selon les différentes présentations cliniques ?","a":"<ul><li><strong>Herpès labial/orofacial (récurrence simple)</strong> : Pas d'antiviral en règle.</li><li><strong>Primo-infection sévère herpètique</strong> : <strong>Aciclovir PO</strong> (ou IV si troubles de déglutition).</li><li><strong>Herpès génital</strong> : <strong>Aciclovir PO</strong> ou <strong>Valaciclovir PO</strong> pendant <strong>5 jours</strong>. Formes sévères (rétention d'urine, douleurs intenses) : <strong>Aciclovir IV</strong> pendant <strong>10 jours</strong>.</li><li><strong>Herpès néonatal</strong> : <strong>Aciclovir IV</strong> pendant <strong>14 jours</strong> (forme localisée) à <strong>21 jours</strong> (forme neuro/disséminée).</li><li><strong>Méningo-encéphalite herpétique</strong> : <strong>Aciclovir IV</strong> pendant <strong>10 jours</strong>, à débuter en urgence et de façon probabiliste.</li></ul>"},{"i":"7fe05b2a3c6a","n":168,"o":"168-15","u":"Prise en charge","t":"Connaître les principes du traitement d’une infection à HSV et à VZV","q":"Comment prend-on en charge les algies post-zostériennes ?","a":"<p>La prise en charge des algies post-zostériennes repose sur :</p><ul><li>Des <strong>antalgiques à visée neuropathique</strong> : <strong>amitriptyline</strong>, <strong>gabapentine</strong> (AMM), prégabaline, carbamazépine (hors AMM).</li><li>Des <strong>topiques</strong> : emplâtre de <strong>lidocaïne</strong> (≤ 12h/jour), <strong>capsaïcine</strong> locale.</li></ul>"},{"i":"8b269dd71bb8","n":168,"o":"168-15","u":"Prise en charge","t":"Connaître les principes du traitement d’une infection à HSV et à VZV","q":"Quelle est la conduite à tenir pour une femme enceinte non immunisée exposée à la varicelle ?","a":"<ul><li>Si le contact avec la varicelle a eu lieu <strong>≤ 96 heures</strong> : administration d'<strong>immunoglobulines spécifiques anti-VZV</strong>.</li><li>Si le contact a eu lieu <strong>> 96 heures</strong> : <strong>pas de traitement spécifique</strong>.</li></ul>"},{"i":"bccae01ea6b7","n":168,"o":"168-15","u":"Prise en charge","t":"Connaître les principes du traitement d’une infection à HSV et à VZV","q":"Quel est le principe général d'action des antiviraux anti-herpès mentions et la molécule pivot de ce traitement ?","a":"<p>Les antiviraux anti-herpès sont <strong>virostatiques</strong> : ils contrôlent une primo-infection ou une réactivation symptomatique mais <strong>n'éradiquent pas le virus latent</strong>, exposant à un risque de récidive à l'arrêt.</p><p>La molécule pivot est l'<strong>aciclovir</strong>, qui inhibe l'ADN polymérase virale après phosphorylation dans les cellules infectées.</p>"},{"i":"c7b9d62e67dd","n":168,"o":"168-15","u":"Prise en charge","t":"Connaître les principes du traitement d’une infection à HSV et à VZV","q":"Quelles sont les indications et les modalités de la prévention des récurrences d'infections à HSV ?","a":"<p>La prévention des récurrences d'infections à HSV est indiquée en cas de <strong>≥ 6 récurrences/an</strong> (génital ou orofacial) et/ou de <strong>formes compliquées</strong>.</p><p>Le traitement consiste en <strong>Valaciclovir</strong> (ou Aciclovir) <strong>PO quotidien au long cours</strong> (<strong>6 à 12 mois</strong>) puis réévaluation. Ce traitement ne permet pas l'éradication du virus.</p>"},{"i":"dfa7fa2f0d4b","n":168,"o":"168-15","u":"Prise en charge","t":"Connaître les principes du traitement d’une infection à HSV et à VZV","q":"Quels sont les principes du traitement de la varicelle et du zona liés au VZV ?","a":"<ul><li><strong>Varicelle bénigne de l'enfant</strong> : Traitement symptomatique (paracétamol, antihistaminique, soins cutanés), <strong>pas d'antiviral</strong>.</li><li><strong>Varicelle grave/à risque</strong> : <strong>Aciclovir IV</strong> pendant <strong>10 jours</strong> si immunodéprimé, complication viscérale, nouveau-né ou femme enceinte en péri-partum.</li><li><strong>Zona</strong> : Antiviral <strong>PO</strong> (<strong>Valaciclovir/Famciclovir 7 jours</strong>) à débuter dans les <strong>72h</strong> si âge > 50 ans, douleurs intenses, zona étendu ou ophtalmique. <strong>Aciclovir IV 7-10 jours</strong> si immunodéprimé. <strong>Pas de corticothérapie générale</strong>.</li></ul>"},{"i":"0cfc7a75e02d","n":168,"o":"168-4","u":"Physiopathologie","t":"Connaître les différentes phases cliniques d’infection des herpès virus","q":"Quelles sont les trois phases cliniques distinctes de l'infection par les herpès virus ?","a":"<p>Les trois phases cliniques sont :</p><ul><li>La <strong>primo-infection</strong>.</li><li>La <strong>latence</strong>.</li><li>La <strong>réactivation</strong>.</li></ul>"},{"i":"181ef2dc4e1d","n":168,"o":"168-4","u":"Physiopathologie","t":"Connaître les différentes phases cliniques d’infection des herpès virus","q":"Caractéristiques de la phase de latence des herpès virus ?","a":"<p>Durant la phase de latence, le virus s'installe en <strong>quiescence virale</strong> dans un <strong>ganglion sensitif</strong>. Il y a transcription du génome viral mais <strong>sans synthèse protéique</strong>, ce qui le rend « endormi », peu accessible à l'immunité et aux traitements, et <strong>non éradicable</strong>.</p>"},{"i":"b1d6c7503d08","n":168,"o":"168-4","u":"Physiopathologie","t":"Connaître les différentes phases cliniques d’infection des herpès virus","q":"Description de la primo-infection par les herpès virus : contact initial, cycle viral, symptômes et lieu de migration.","a":"<p>La primo-infection est le <strong>premier contact infectant</strong>, sur une muqueuse ou la peau. Après une incubation de <strong>2 à 7 jours</strong> (pour l'HSV), le virus effectue un cycle productif dans les kératinocytes, entraînant une ballonisation et des <strong>vésicules inflammatoires</strong>. Elle est le plus souvent <strong>asymptomatique</strong> (environ 80% des cas), mais peut être symptomatique (environ 20%). Le virus migre ensuite de façon <strong>antérograde</strong> le long des nerfs sensitifs jusqu'au ganglion.</p>"},{"i":"d5866ba4a634","n":168,"o":"168-4","u":"Physiopathologie","t":"Connaître les différentes phases cliniques d’infection des herpès virus","q":"Description de la phase de réactivation des herpès virus : migration, formes cliniques et cas particulier du VZV ?","a":"<p>La réactivation implique une <strong>migration rétrograde</strong> du virus vers la peau ou la muqueuse, recolonisant le territoire d'innervation. Elle peut prendre deux formes :</p><ul><li>La <strong>récurrence</strong>, qui est une réactivation symptomatique (environ 20% des cas).</li><li>L'<strong>excrétion virale asymptomatique</strong>, qui ne présente pas de signes cliniques mais est contagieuse (environ 80% des cas).</li></ul><p>Dans le cas du <strong>VZV</strong>, la primo-infection est la <strong>varicelle</strong>, et la réactivation symptomatique est le <strong>zona</strong>.</p>"},{"i":"1372e8228c38","n":168,"o":"168-5","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une primo infection et d’une récurrence à HSV 1 et 2","q":"Comment le diagnostic d'une récurrence herpétique se manifeste-t-il cliniquement ?","a":"<ul><li>Présence de <strong>prodromes stéréotypés</strong> (dysesthésie cuisante, picotements, prurit) quelques heures avant l'éruption.</li><li>La topographie est <strong>stéréotypée</strong> chez un patient donné, souvent au même siège que la primo-infection (labiale > génitale > cutanée, nasale, oculaire).</li><li>L'éruption est caractérisée par des <strong>vésicules en bouquet</strong>, évoluant vers des érosions puis des croûtes.</li><li>La cicatrisation se fait en <strong>7 à 14 jours</strong>, avec une contagiosité de 2 à 4 jours.</li></ul>"},{"i":"6f1c29d09b93","n":168,"o":"168-5","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une primo infection et d’une récurrence à HSV 1 et 2","q":"Quels sont les tableaux cliniques des primo-infections herpétiques symptomatiques au niveau oral et génital ?","a":"<ul><li><strong>Gingivostomatite herpétique (HSV-1)</strong> : typiquement chez l'enfant, c'est la forme la plus courante de primo-infection orale.</li><li><strong>Herpès génital (majoritairement HSV-2, HSV-1 en hausse)</strong> : il s'agit d'une IST, première cause d'ulcérations génitales dans les pays développés, se manifestant par une <strong>vulvovaginite aiguë brutale, des douleurs intenses, des érosions polycycliques</strong>, parfois un tableau pseudo-grippal et des adénopathies inguinales. La <strong>rétention urinaire</strong> est un signe de gravité.</li></ul>"},{"i":"994d106b3e51","n":168,"o":"168-5","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une primo infection et d’une récurrence à HSV 1 et 2","q":"Quel est l'intérêt de la sérologie HSV dans le diagnostic d'une infection herpétique ?","a":"<p>La sérologie HSV a un <strong>intérêt limité</strong> car 80% des adultes sont IgG positifs, rendant son interprétation difficile pour un diagnostic aigu. Elle n'est utile que pour <strong>documenter une séroconversion</strong> dans le cadre d'une primo-infection, ce qui nécessite deux prélèvements à 10 jours d'intervalle.</p>"},{"i":"9e3a54f41191","n":168,"o":"168-5","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une primo infection et d’une récurrence à HSV 1 et 2","q":"Comment établit-on le diagnostic d'une primo-infection herpétique cutanéo-muqueuse typique, en dehors des méningo-encéphalites et en l'absence de terrain à risque ?","a":"<p>Le diagnostic est <strong>essentiellement clinique</strong>. Aucun examen complémentaire n'est nécessaire.</p>"},{"i":"dd320870a876","n":168,"o":"168-5","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une primo infection et d’une récurrence à HSV 1 et 2","q":"Dans quelles situations et par quel examen paraclinique doit-on établir le diagnostic d'une infection herpétique atypique, grave ou sur terrain à risque ?","a":"<p>Dans les formes <strong>atypiques, graves ou sur terrain à risque</strong>, le diagnostic est établi par <strong>biologie directe</strong>. La technique de référence est la <strong>PCR HSV sur écouvillonnage d'une vésicule récente</strong>, qui offre un résultat en moins de 24 heures et est très sensible et spécifique.</p>"},{"i":"ff2176581b05","n":168,"o":"168-5","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une primo infection et d’une récurrence à HSV 1 et 2","q":"Quels sont les signes cliniques communs de la lésion élémentaire cutanéo-muqueuse au cours d'une infection à HSV ?","a":"<ul><li>Une <strong>vésicule groupée en « bouquet »</strong> sur un fond érythémateux.</li><li>Cette lésion évolue vers des <strong>érosions post-vésiculeuses arrondies, coalescentes, à contours polycycliques</strong>.</li><li>Enfin, elle se couvre de <strong>croûtes</strong>.</li></ul>"},{"i":"4181470bde1c","n":168,"o":"168-7","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une varicelle et ses principales complications","q":"Quelles sont les principales complications de la varicelle à rechercher ?","a":"<p>Les principales complications, survenant dans <strong>3 à 5% des cas</strong>, sont :</p><ul><li>Les <strong>surinfections bactériennes</strong> (les plus fréquentes), favorisées par le grattage et les AINS, impliquant <em>S. aureus</em> ou <em>S. pyogenes</em> (SGA), pouvant se manifester par impétiginisation, dermohypodermite, fasciite nécrosante, syndromes toxiniques ou sepsis.</li><li>La <strong>pneumopathie varicelleuse</strong>, surtout chez l'adulte (facteurs de risque : tabac, grossesse), survenant 1 à 6 jours après l'éruption, avec toux, dyspnée, fièvre, hémoptysies, et opacités micro- et macronodulaires, responsable d'environ 30% des décès chez l'adulte.</li><li>Les complications <strong>neurologiques</strong> : convulsions hyperthermiques, <strong>cérébellite</strong> (la plus fréquente et bénigne), encéphalite, myélite. Attention au <strong>syndrome de Reye</strong> lié à l'aspirine (encéphalopathie et stéatose hépatique), mortel dans 80% des cas.</li><li>La <strong>varicelle profuse</strong> chez l'immunodéprimé, forme ulcéro-nécrotique, hémorragique, avec purpura fulminans, CIVD, et atteintes viscérales.</li></ul>"},{"i":"9d702c966e5b","n":168,"o":"168-7","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une varicelle et ses principales complications","q":"Comment poser le diagnostic clinique de la varicelle ?","a":"<p>La varicelle est une primo-infection par le VZV après une incubation d'environ <strong>14 jours</strong>. Elle se manifeste par un tableau d'<strong>exanthème vésiculeux prurigineux fébrile</strong>, avec une évolution <strong>descendante</strong> (cuir chevelu → face → tronc), respectant les paumes et les plantes. La sémiologie de l'éruption est caractérisée par :</p><ul><li>Un <strong>prurit intense</strong> et une fièvre modérée (38-39°C).</li><li>Des lésions typiques, apparaissant comme une <strong>vésicule à contenu clair puis trouble</strong>, bordée d'une auréole rouge, désignée comme une « <strong>goutte de rosée sur peau saine</strong> ».</li><li>Ces vésicules évoluent vers l'ombilication, puis la formation de croûtes J4, et une cicatrisation J10.</li><li>L'éruption se fait par <strong>2 à 3 poussées</strong> successives, entraînant la <strong>coexistence d'éléments d'âges différents</strong>, signe sémiologique majeur.</li><li>Peuvent s'y associer un <strong>énanthème buccal érosif</strong> et des micropolyadénopathies cervicales.</li></ul>"},{"i":"b74f194be9cd","n":168,"o":"168-7","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une varicelle et ses principales complications","q":"Quelles sont les contre-indications absolues et les terrains à risque de forme grave lors d'une varicelle ?","a":"<p>Les contre-indications absolues sont :</p><ul><li>L'<strong>aspirine</strong> en raison du risque de <strong>syndrome de Reye</strong>.</li><li>Les <strong>AINS</strong> en raison du risque de <strong>fasciite nécrosante</strong>.</li><li>Les topiques (talc, anesthésiques) qui masquent une surinfection.</li></ul><p>Les terrains à risque de forme grave sont :</p><ul><li>L'<strong>adulte</strong> et l'<strong>adolescent > 12 ans</strong>.</li><li>La <strong>femme enceinte</strong>.</li><li>Le <strong>nouveau-né/nourrisson</strong> (surtout < 1 an) et le prématuré.</li><li>L'<strong>immunodéprimé</strong>, qui peut développer des formes ulcéro-hémorragiques ou viscérales.</li></ul>"},{"i":"26574dde7b59","n":168,"o":"168-8","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’un zona","q":"Décrivez la sémiologie cutanée évolutive d'un zona typique.","a":"<p>La phase éruptive du zona progresse typiquement comme suit :</p><ul><li>Début par un <strong>placard érythémateux</strong>.</li><li>Apparition de <strong>vésicules groupées en bouquet</strong>, initialement à liquide clair, puis devenant trouble.</li><li>Les vésicules évoluent en <strong>érosions</strong> vers J5.</li><li>Formation de <strong>croûtes</strong> vers J7.</li><li>Persistance fréquente de <strong>cicatrices dépigmentées</strong>, parfois indélébiles, à partir de J10.</li></ul>"},{"i":"5e1fb41de70d","n":168,"o":"168-8","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’un zona","q":"Quelle est la topographie caractéristique du zona et ses formes cliniques particulières ?","a":"<p>La topographie caractéristique du zona est <strong>unilatérale</strong> et <strong>monomérique</strong>, ne dépassant jamais la ligne médiane. Les localisations les plus fréquentes sont <strong>intercostale, dorso-lombaire ou sacrée</strong> (décrite comme une « demi-ceinture »).</p><p>Il existe des formes céphaliques spécifiques :</p><ul><li>Le <strong>zona ophtalmique (V1)</strong>.</li><li>Le zona bucco-pharyngé.</li><li>Le zona du ganglion géniculé.</li></ul>"},{"i":"848d0f91dd15","n":168,"o":"168-8","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’un zona","q":"Quels sont les signes cliniques de la phase prodromique du zona ?","a":"<p>La phase prodromique (3 à 4 jours avant l'éruption) du zona est caractérisée par :</p><ul><li>Des <strong>douleurs neuropathiques</strong> (brûlures, coup de poignard, paroxysmes).</li><li>Des <strong>paresthésies</strong> et des troubles sensitifs.</li><li>Ces signes sont <strong>radiculaires</strong> et <strong>unilatéraux</strong>, sur le territoire qui sera le siège de l'éruption.</li></ul>"},{"i":"84b6213da309","n":168,"o":"168-8","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’un zona","q":"Comment définir cliniquement le zona ?","a":"<p>Le zona est la réactivation du <strong>Virus Varicelle-Zona (VZV)</strong>, se manifestant par une éruption cutanée <strong>localisée, unilatérale et métamérique</strong> (correspondant à un territoire radiculaire sensitif).</p>"},{"i":"91a71b5b2ead","n":168,"o":"168-8","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’un zona","q":"Devant quels signes cliniques évoquer une immunodépression chez un patient présentant un zona ?","a":"<p>Une immunodépression doit être recherchée devant un zona chez un <strong>sujet jeune (&lt; 50 ans)</strong> ou en présence d'un <strong>zona étendu ou atypique</strong>.</p><p>Le bilan doit inclure une <strong>sérologie VIH</strong> et une <strong>NFS</strong> (pour rechercher une hémopathie comme une LLC).</p>"},{"i":"a09f05871e4c","n":168,"o":"168-8","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’un zona","q":"Dans quelles situations la PCR VZV est-elle indiquée pour confirmer le diagnostic de zona ?","a":"<p>Le diagnostic du zona est <strong>principalement clinique</strong>. La confirmation par <strong>PCR VZV</strong> (à partir d'un écouvillonnage du contenu vésiculaire) ne se justifie que :</p><ul><li>Devant une forme <strong>sévère, compliquée ou atypique</strong>.</li><li>En cas de nécessité de certitude diagnostique, notamment chez la <strong>femme enceinte</strong>.</li></ul>"},{"i":"06140da877e6","n":168,"o":"168-9","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic des principales complications du zona (kératite, douleurs post-zostériennes, neurologiques)","q":"Quelles sont les caractéristiques des formes graves de zona, notamment chez le patient immunodéprimé ?","a":"<p>Chez le patient immunodéprimé, les formes graves de zona peuvent se manifester par :</p><ul><li>Une extension <strong>bilatérale ou multi-métamérique</strong>.</li><li>Un aspect <strong>ulcéro-hémorragique et nécrotique</strong> des lésions.</li><li>Un zona « généralisé » (<strong>varicelliforme</strong>).</li><li>Des atteintes <strong>viscérales</strong>.</li></ul>"},{"i":"22999128583a","n":168,"o":"168-9","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic des principales complications du zona (kératite, douleurs post-zostériennes, neurologiques)","q":"Comment définir les algies post-zostériennes ?","a":"<p>Les algies post-zostériennes sont des <strong>douleurs qui persistent plus de 1 mois</strong> après l'épisode aigu de zona. Elles disparaissent habituellement en 6 mois, mais peuvent devenir définitives et invalidantes.</p>"},{"i":"4e868499f241","n":168,"o":"168-9","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic des principales complications du zona (kératite, douleurs post-zostériennes, neurologiques)","q":"Quelles sont les complications neurologiques du zona à connaître ?","a":"<p>Les principales complications neurologiques du zona sont :</p><ul><li>Une <strong>atteinte motrice</strong> dans le métamère du zona.</li><li>Une <strong>myélite</strong>.</li><li>Une <strong>encéphalite</strong>, qui peut survenir parfois même sans éruption cutanée visible.</li></ul>"},{"i":"64b503543af7","n":168,"o":"168-9","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic des principales complications du zona (kératite, douleurs post-zostériennes, neurologiques)","q":"Comment diagnostiquer la kératite zostérienne, principale complication oculaire du zona ophtalmique ?","a":"<p>La kératite zostérienne se diagnostique par la présence d'une ulcération cornéenne, typiquement <strong>dendritiforme</strong>, mise en évidence par un test à la <strong>fluorescéine</strong> lors de l'examen ophtalmologique.</p>"}]};